```rust
// src/gameplay/arc_formula.rs — ArcFormula.cs 1:1 port
use crate::values::*;
use crate::chart::types::ArcLineType;
use std::f32::consts::FRAC_PI_2;

// === Coordinate Transforms ===

pub fn arc_x_to_world(x: f32) -> f32 {
    -LANE_WIDTH * 2.0 * x + LANE_WIDTH
}

pub fn arc_y_to_world(y: f32) -> f32 {
    ARC_Y0 + (ARC_Y1 - ARC_Y0) * y
}

pub fn world_x_to_arc(x: f32) -> f32 {
    (x - LANE_WIDTH) / (-LANE_WIDTH * 2.0)
}

pub fn world_y_to_arc(y: f32) -> f32 {
    (y - ARC_Y0) / (ARC_Y1 - ARC_Y0)
}

pub fn lane_to_world_x(lane: i32) -> f32 {
    -LANE_WIDTH * lane as f32 + LANE_WIDTH * 2.5
}

pub fn lane_to_arc_x(lane: i32) -> f32 {
    0.5 * lane as f32 - 0.75
}

pub fn arc_x_to_lane(x: f32) -> f32 {
    (x + 0.75) / 0.5
}

pub fn world_x_to_lane(x: f32) -> i32 {
    ((x - LANE_WIDTH * 2.5) / -LANE_WIDTH).round() as i32
}

// === Z / Floor Position ===

pub fn z_to_floor_position(z: f32, drop_rate: f32, base_bpm: f64) -> f64 {
    (z as f64 / drop_rate as f64 * base_bpm * -1000.0)
}

pub fn floor_position_to_z(fp: f64, drop_rate: f32, base_bpm: f64) -> f32 {
    (fp / base_bpm * drop_rate as f64 / -1000.0) as f32
}

pub fn within_render_range(z: f32) -> bool {
    z >= -TRACK_LENGTH_FORWARD && z <= TRACK_LENGTH_BACKWARD
}

// === Easing Functions ===

fn s(start: f32, end: f32, t: f32) -> f32 {
    (1.0 - t) * start + t * end
}

fn o(start: f32, end: f32, t: f32) -> f32 {
    start + (end - start) * (1.0 - (FRAC_PI_2 * t).cos())
}

fn i(start: f32, end: f32, t: f32) -> f32 {
    start + (end - start) * (FRAC_PI_2 * t).sin()
}

fn b(start: f32, end: f32, t: f32) -> f32 {
    let o = 1.0 - t;
    o * o * o * start + 3.0 * o * o * t * start + 3.0 * o * t * t * end + t * t * t * end
}

pub fn arc_x(start: f32, end: f32, t: f32, line_type: ArcLineType) -> f32 {
    match line_type {
        ArcLineType::S => s(start, end, t),
        ArcLineType::B => b(start, end, t),
        ArcLineType::Si | ArcLineType::SiSi | ArcLineType::SiSo => i(start, end, t),
        ArcLineType::So | ArcLineType::SoSi | ArcLineType::SoSo => o(start, end, t),
    }
}

pub fn arc_y(start: f32, end: f32, t: f32, line_type: ArcLineType) -> f32 {
    match line_type {
        ArcLineType::S | ArcLineType::Si | ArcLineType::So => s(start, end, t),
        ArcLineType::B => b(start, end, t),
        ArcLineType::SiSi | ArcLineType::SoSi => i(start, end, t),
        ArcLineType::SiSo | ArcLineType::SoSo => o(start, end, t),
    }
}

// === Utility ===

pub fn qi(value: f32) -> f32 {
    value * value * value
}

pub fn qo(value: f32) -> f32 {
    let v = value - 1.0;
    v * v * v + 1.0
}

pub fn calculate_tap_size_scalar(z: f32) -> f32 {
    if z <= 0.0 {
        (1.5 + 6.25 * (-z) / TRACK_LENGTH_FORWARD).abs()
    } else {
        (1.5 + 7.25 * z / TRACK_LENGTH_BACKWARD).abs()
    }
}

pub fn calculate_beatline_size_scalar(thickness: f32, z: f32) -> f32 {
    if z <= 0.0 {
        thickness * (1.0 + 3.0 * z / TRACK_LENGTH_FORWARD).abs()
    } else {
        thickness * (1.0 + 3.0 * z / TRACK_LENGTH_BACKWARD).abs()
    }
}

pub fn calculate_fade_out_alpha(z: f32) -> f32 {
    if z <= 0.0 {
        ((TRACK_LENGTH_FORWARD + z) / NOTE_FADE_OUT_LENGTH).clamp(0.0, 1.0)
    } else {
        ((TRACK_LENGTH_BACKWARD - z) / NOTE_FADE_OUT_LENGTH).clamp(0.0, 1.0)
    }
}

pub fn calculate_arc_lock_duration(interval: f32) -> i32 {
    (interval * 4.0).round().min(1000.0) as i32
}

pub fn calculate_arc_segment_length(duration: i32, resolution: f32) -> f32 {
    let base = ARC_SEGMENT_LENGTH / resolution;
    if duration < 1000 { base } else { base * 2.0 }
}

/// Calculate long note (hold/arc) judge timings.
/// Returns (time_increment, total_combo, first_judge_time).
pub fn calculate_long_note_judge_timings(
    timing: i32,
    end_timing: i32,
    bpm: f32,
    density: f32,
    is_first_of_group: bool,
) -> (f32, i32, i32) {
    let bpm_abs = bpm.abs();
    let time_increment = if bpm_abs >= 255.0 {
        60_000.0 / bpm_abs / density
    } else {
        30_000.0 / bpm_abs / density
    };

    let duration = (end_timing - timing) as f32;
    let count = (duration / time_increment) as i32;
    let offset = if is_first_of_group { 0 } else { 1 } ^ 1;

    if count <= offset {
        let first = timing + (duration / 2.0) as i32;
        (time_increment, 1, first)
    } else {
        let total = count - offset;
        let first = timing + (offset as f32 * time_increment) as i32;
        (time_increment, total, first)
    }
}
