// src/gameplay/arc_mesh.rs — ArcMeshGenerator.cs 1:1 port
use glam::Vec3;

pub struct MeshData {
    pub vertices: Vec<Vec3>,
    pub triangles: Vec<u32>,
}

/// 三角棱柱 body mesh (6 vertices, 4 triangles)
pub fn generate_body_mesh(offset: f32) -> MeshData {
    let half = offset / 2.0;
    MeshData {
        vertices: vec![
            Vec3::new(0.0, half, 0.0),       // 0: top center near
            Vec3::new(0.0, half, 1.0),       // 1: top center far
            Vec3::new(offset, -half, 1.0),   // 2: right far
            Vec3::new(offset, -half, 0.0),   // 3: right near
            Vec3::new(-offset, -half, 1.0),  // 4: left far
            Vec3::new(-offset, -half, 0.0),  // 5: left near
        ],
        triangles: vec![
            0, 3, 2,
            0, 2, 1,
            0, 1, 4,
            0, 4, 5,
        ],
    }
}

/// Pyramid head mesh (4 vertices, 2 triangles)
pub fn generate_head_mesh(offset: f32) -> MeshData {
    let half = offset / 2.0;
    MeshData {
        vertices: vec![
            Vec3::new(0.0, half, 0.0),       // 0: top
            Vec3::new(offset, -half, 0.0),   // 1: right
            Vec3::new(0.0, -half, half),     // 2: forward
            Vec3::new(-offset, -half, 0.0),  // 3: left
        ],
        triangles: vec![
            0, 2, 1,
            0, 3, 2,
        ],
    }
}

/// Shadow mesh (flat rectangle, 4 vertices, 2 triangles)
pub fn generate_shadow_mesh(offset: f32) -> MeshData {
    MeshData {
        vertices: vec![
            Vec3::new(offset, 0.0, 0.0),
            Vec3::new(offset, 0.0, 1.0),
            Vec3::new(-offset, 0.0, 1.0),
            Vec3::new(-offset, 0.0, 0.0),
        ],
        triangles: vec![
            0, 1, 3,
            1, 2, 3,
        ],
    }
}

