        pipeline: wgpu::RenderPipeline,
        texture_bind_group: wgpu::BindGroup,
        initial_capacity: u32,
    ) -> Self { /* ... */ }

    pub fn clear(&mut self) {
        self.instance_data.clear();
    }

    pub fn add(&mut self, instance: InstanceData) {
        self.instance_data.push(instance);
    }

    pub fn upload(&mut self, queue: &wgpu::Queue, device: &wgpu::Device) {
        // Grow buffer if needed, then queue.write_buffer
    }

    pub fn draw<'a>(&'a self, pass: &mut wgpu::RenderPass<'a>) {
        if self.instance_data.is_empty() { return; }
        pass.set_pipeline(&self.pipeline);
        pass.set_vertex_buffer(0, self.vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, self.instance_buffer.slice(..));
        pass.set_index_buffer(self.index_buffer.slice(..), wgpu::IndexFormat::Uint32);
        pass.set_bind_group(1, &self.texture_bind_group, &[]);
        pass.draw_indexed(0..self.index_count, 0, 0..self.instance_data.len() as u32);
    }
}
