```rust
// src/render/render_service.rs
pub struct ArcDrawCall {
    pub instance: InstanceData,
    pub depth: f32,
}

pub struct RenderService {
    // Per-type instanced renderers
    pub hold_drawer: InstancedRenderer,
    pub tap_drawer: InstancedRenderer,
    pub arc_drawer: SortedDrawer,      // depth-sorted
    pub trace_drawer: SortedDrawer,    // depth-sorted
    pub arc_shadow_drawer: InstancedRenderer,
    pub trace_shadow_drawer: InstancedRenderer,
    pub arc_head_drawer: InstancedRenderer,
    pub trace_head_drawer: InstancedRenderer,
    pub arc_cap_drawer: InstancedRenderer,
    pub arctap_drawer: InstancedRenderer,
    pub arctap_shadow_drawer: InstancedRenderer,
    pub height_indicator_drawer: InstancedRenderer,
    pub connection_line_drawer: InstancedRenderer,
    pub beatline_drawer: InstancedRenderer,
    pub particle_drawer: InstancedRenderer,
}

pub struct SortedDrawer {
    calls: Vec<ArcDrawCall>,
    renderer: InstancedRenderer,
}

impl SortedDrawer {
    pub fn add(&mut self, instance: InstanceData, depth: f32) {
        self.calls.push(ArcDrawCall { instance, depth });
    }

    pub fn flush(&mut self) {
        // Sort by depth ascending (back-to-front)
        self.calls.sort_by(|a, b| a.depth.partial_cmp(&b.depth).unwrap());
        for call in &self.calls {
            self.renderer.add(call.instance);
        }
        self.calls.clear();
    }
}
```

