// src/score/service.rs
use crate::judgment::requests::JudgmentResult;
use crate::values::*;

pub struct ScoreEvent {
    pub timing: i32,
    pub score: f64,
}

pub struct ScoreService {
    pub note_count: i32,
    score_per_note: f64,
    current_score_full: f64,
    current_score_partial: f64,
    pending_events: Vec<ScoreEvent>,
    pub combo: i32,
    pub max_combo: i32,
    pub combo_redmix: f32,
    // counts
    pub max_count: i32,
    pub perfect_early_count: i32,
    pub perfect_late_count: i32,
    pub good_early_count: i32,
    pub good_late_count: i32,
    pub miss_count: i32,
}

impl ScoreService {
    pub fn new(note_count: i32) -> Self {
        Self {
            note_count,
            score_per_note: MAX_SCORE as f64 / note_count as f64,
            current_score_full: 0.0,
            current_score_partial: 0.0,
            pending_events: Vec::new(),
            combo: 0,
            max_combo: 0,
            combo_redmix: 0.0,
            max_count: 0,
            perfect_early_count: 0,
            perfect_late_count: 0,
            good_early_count: 0,
            good_late_count: 0,
            miss_count: 0,
        }
    }

    pub fn process_judgment(&mut self, result: JudgmentResult, timing: i32) {
        let score = if result.is_max() {
            self.score_per_note + 1.0
        } else if result.is_good() {
            self.score_per_note * GOOD_PENALTY_MULTIPLIER
        } else if result.is_miss() {
            0.0
        } else {
            self.score_per_note // Perfect (non-max)
        };

        self.pending_events.push(ScoreEvent { timing, score });

        if result.is_miss() {
            self.combo = 0;
            self.combo_redmix = 1.0;
        } else {
            self.combo += 1;
            self.max_combo = self.max_combo.max(self.combo);
        }

        // Update counts
        match result {
            JudgmentResult::Max => self.max_count += 1,
            JudgmentResult::PerfectEarly => self.perfect_early_count += 1,
            JudgmentResult::PerfectLate => self.perfect_late_count += 1,
            JudgmentResult::GoodEarly => self.good_early_count += 1,
            JudgmentResult::GoodLate => self.good_late_count += 1,
            _ => self.miss_count += 1,
        }
    }

    pub fn update(&mut self, current_timing: i32, delta_time: f32) {
        self.current_score_partial = 0.0;
        self.pending_events.retain(|e| {
            let elapsed = current_timing - e.timing;
            if elapsed >= SCORE_MODIFY_DELAY {
                self.current_score_full += e.score;
                false
            } else {
                let partial = elapsed as f64 / SCORE_MODIFY_DELAY as f64;
                self.current_score_partial += partial * e.score;
                true
            }
        });
        self.combo_redmix = (self.combo_redmix - delta_time / COMBO_LOST_FLASH_DURATION).max(0.0);
    }

    pub fn current_score(&self) -> i32 {
        (self.current_score_full + self.current_score_partial) as i32
    }
}
```

