// src/render/camera.rs — ArcCreate CameraService 1:1
use glam::{Vec3, Mat4, Quat};
use crate::values::*;

pub struct CameraService {
    pub position: Vec3,
    pub rotation: Quat,
    pub fov: f32,
    pub aspect: f32,
    pub near: f32,
    pub far: f32,
    // tilt
    current_tilt: f32,
    current_arc_pos: f32,
    // aspect adjustment
    aspect_adjustment: f32,
    // screen size
    screen_width: f32,
    screen_height: f32,
}

impl CameraService {
    pub fn new(width: f32, height: f32) -> Self {
        let mut cam = Self {
            position: Vec3::ZERO,
            rotation: Quat::IDENTITY,
            fov: 50.0,
            aspect: width / height,
            near: 0.01,
            far: 1000.0,
            current_tilt: 0.0,
            current_arc_pos: 0.0,
            aspect_adjustment: 0.0,
            screen_width: width,
            screen_height: height,
        };
        cam.recalculate_aspect(width, height);
        cam.reset();
        cam
    }

    pub fn recalculate_aspect(&mut self, width: f32, height: f32) {
        self.screen_width = width;
        self.screen_height = height;
        self.aspect = width / height;
        let equivalent_height = height / (width / 16.0);
        self.aspect_adjustment = ((equivalent_height - 9.0) / 3.0).clamp(0.0, 1.0);
    }

    pub fn reset(&mut self) {
        let a = self.aspect_adjustment;
        self.position = Vec3::new(
            0.0,
            CAMERA_Y,
            lerp(CAMERA_Z, CAMERA_Z_TABLET, a),
        );
        let rot_x = lerp(CAMERA_ROT_X, CAMERA_ROT_X_TABLET, a);
        self.rotation = Quat::from_euler(
            glam::EulerRot::YXZ,
            std::f32::consts::PI, // 180° Y
            -rot_x.to_radians(),  // X rotation (negative = look down)
            0.0,
        );
        self.fov = lerp(50.0, 65.0, a);
        self.current_tilt = 0.0;
    }

    pub fn update(&mut self, delta_time: f32, arc_pos: f32) {
        self.current_arc_pos = arc_pos;
        let tilt_target = -(arc_pos / LANE_WIDTH).clamp(-1.0, 1.0) * CAMERA_ARC_POS_SCALAR;
        self.current_tilt = lerp(
            self.current_tilt,
            tilt_target,
            CAMERA_TILT_SPEED * delta_time,
        );
    }

    pub fn view_matrix(&self) -> Mat4 {
        let up = Vec3::new(
            self.current_tilt,
            1.0 - self.current_tilt.abs(),
            0.0,
        ).normalize();
        let forward = self.rotation * Vec3::NEG_Z;
        let target = self.position + forward;
        Mat4::look_at_rh(self.position, target, up)
    }

    pub fn projection_matrix(&self) -> Mat4 {
        Mat4::perspective_rh(
            self.fov.to_radians(),
            self.aspect,
            self.near,
            self.far,
        )
    }

    pub fn view_proj(&self) -> Mat4 {
        self.projection_matrix() * self.view_matrix()
    }

    pub fn calculate_depth_squared(&self, world_pos: Vec3) -> f32 {
        (world_pos - self.position).length_squared()
    }
}

fn lerp(a: f32, b: f32, t: f32) -> f32 {
    a + (b - a) * t
}
```

