```wgsl
// src/render/shaders/track.wgsl — ArcCreate Track.shader port
struct CameraUniform { view_proj: mat4x4<f32> }
@group(0) @binding(0) var<uniform> camera: CameraUniform;

struct TrackUniforms {
    edge_l_alpha: f32,
    lane1_alpha: f32,
    lane2_alpha: f32,
    lane3_alpha: f32,
    lane4_alpha: f32,
    edge_r_alpha: f32,
    _pad0: f32,
    _pad1: f32,
}
@group(1) @binding(0) var<uniform> track: TrackUniforms;
@group(2) @binding(0) var tex: texture_2d<f32>;
@group(2) @binding(1) var tex_sampler: sampler;

struct VsIn {
    @location(0) position: vec3<f32>,
    @location(1) color: vec4<f32>,
    @location(2) uv: vec2<f32>,
}

struct VsOut {
    @builtin(position) clip_position: vec4<f32>,
    @location(0) color: vec4<f32>,
    @location(1) uv: vec2<f32>,
}

@vertex
fn vs_main(in: VsIn) -> VsOut {
    var out: VsOut;
    out.clip_position = camera.view_proj * vec4<f32>(in.position, 1.0);
    out.color = in.color;
    out.uv = in.uv;
    return out;
}

// Lane boundary UV.x values (ArcCreate Track.shader)
const EDGE_L_MAX: f32 = 0.1275;
const LANE1_MAX: f32 = 0.3475;
const LANE2_MAX: f32 = 0.5025;
const LANE3_MAX: f32 = 0.6575;
const LANE4_MAX: f32 = 0.8725;

@fragment
fn fs_main(in: VsOut) -> @location(0) vec4<f32> {
    let tex_color = textureSample(tex, tex_sampler, in.uv);
    var alpha = 1.0;
    let u = in.uv.x;
    if u < EDGE_L_MAX {
        alpha = track.edge_l_alpha;
    } else if u < LANE1_MAX {
        alpha = track.lane1_alpha;
    } else if u < LANE2_MAX {
        alpha = track.lane2_alpha;
    } else if u < LANE3_MAX {
        alpha = track.lane3_alpha;
    } else if u < LANE4_MAX {
        alpha = track.lane4_alpha;
    } else {
        alpha = track.edge_r_alpha;
    }
    var color = tex_color * in.color;
    color.a *= alpha;
    return color;
}
```

