```rust
// src/chart/timing_group.rs
use crate::chart::types::{TimingEvent, GroupProperties};

pub struct TimingGroup {
    pub id: usize,
    pub timings: Vec<TimingEvent>,
    pub properties: GroupProperties,
}

impl TimingGroup {
    pub fn recalculate_floor_positions(&mut self) {
        let mut fp: f64 = 0.0;
        for i in 0..self.timings.len() {
            self.timings[i].floor_position = fp;
            if i + 1 < self.timings.len() {
                let dt = (self.timings[i + 1].time - self.timings[i].time) as f64;
                fp += self.timings[i].bpm as f64 * dt;
            }
        }
    }

    pub fn get_floor_position(&self, timing: i32) -> f64 {
        let event = self.get_event_at(timing);
        event.floor_position + event.bpm as f64 * (timing - event.time) as f64
    }

    pub fn get_bpm(&self, timing: i32) -> f32 {
        self.get_event_at(timing).bpm
    }

    fn get_event_at(&self, timing: i32) -> &TimingEvent {
        // Binary search for the last event with time <= timing
        let idx = self.timings.partition_point(|e| e.time <= timing);
        &self.timings[if idx > 0 { idx - 1 } else { 0 }]
    }
}
```

