// src/judgment/requests.rs

#[derive(Clone, Copy, PartialEq)]
pub enum JudgmentResult {
    Max,
    PerfectEarly,
    PerfectLate,
    GoodEarly,
    GoodLate,
    MissEarly,
    MissLate,
}

impl JudgmentResult {
    pub fn from_offset(offset: i32) -> Self {
        let abs = offset.abs();
        if abs <= 25 { Self::Max }
        else if abs <= 50 { if offset < 0 { Self::PerfectEarly } else { Self::PerfectLate } }
        else if abs <= 100 { if offset < 0 { Self::GoodEarly } else { Self::GoodLate } }
        else { if offset < 0 { Self::MissEarly } else { Self::MissLate } }
    }

    pub fn is_miss(&self) -> bool {
        matches!(self, Self::MissEarly | Self::MissLate)
    }

    pub fn is_max(&self) -> bool { matches!(self, Self::Max) }
    pub fn is_good(&self) -> bool { matches!(self, Self::GoodEarly | Self::GoodLate) }
}

