// src/gameplay/arc_color.rs
pub struct ArcColorState {
    pub assigned_finger_id: Option<u32>,
    pub lock_until: i32,
    pub grace_until: i32,
    pub current_red_arc_value: f32,
    pub red_arc_duration: f32,
    // frame-local
    min_distance_this_frame: f32,
    assigned_finger_missed: bool,
    wrong_finger_hit: bool,
}

pub struct ArcColorLogic {
    pub colors: Vec<ArcColorState>,
    last_frame_timing: i32,
}

impl ArcColorLogic {
    pub fn new_frame(&mut self, timing: i32) {
        let delta = (timing - self.last_frame_timing) as f32;
        self.last_frame_timing = timing;
        for state in &mut self.colors {
            state.reset_intraframe();
            state.update_red_arc_value(delta);
        }
    }

    pub fn flash_red_arc(&mut self, color: usize, interval: f32) {
        let state = &mut self.colors[color];
        if state.current_red_arc_value > 0.0 { return; }
        state.current_red_arc_value = 1.0;
        state.red_arc_duration = crate::gameplay::arc_formula::calculate_arc_lock_duration(interval) as f32;
    }

    pub fn get_red_value(&self, color: usize) -> f32 {
        self.colors[color].current_red_arc_value
    }
}
