/// Time in milliseconds from chart start (Arcaea native unit).
pub type Ms = i32;

#[derive(Debug, Clone)]
pub struct Chart {
    pub audio_offset: Ms,
    pub timing_point_density_factor: f32,
    pub groups: Vec<TimingGroup>,
}

#[derive(Debug, Clone, Default)]
pub struct TimingGroup {
    pub attributes: GroupAttrs,
    pub timings: Vec<Timing>,
    pub taps: Vec<Tap>,
    pub holds: Vec<Hold>,
    pub arcs: Vec<Arc>,
    pub cameras: Vec<CameraEvent>,
    pub scene_controls: Vec<SceneControl>,
}

#[derive(Debug, Clone, Default)]
pub struct GroupAttrs {
    pub no_input: bool,
    pub no_clip: bool,
    pub no_height_indicator: bool,
    pub no_shadow: bool,
    pub no_head: bool,
    pub no_arc_cap: bool,
    pub no_connection: bool,
    pub fading_holds: bool,
    pub ignore_mirror: bool,
    pub autoplay: bool,
    pub arc_resolution: Option<f32>,
    pub angle_x: Option<f32>,
    pub angle_y: Option<f32>,
}

#[derive(Debug, Clone, Copy)]
pub struct Tap {
    pub time: Ms,
    pub lane: f32,
}

#[derive(Debug, Clone, Copy)]
pub struct Hold {
    pub start: Ms,
    pub end: Ms,
    pub lane: f32,
}

#[derive(Debug, Clone)]
pub struct Arc {
    pub start: Ms,
    pub end: Ms,
    pub x1: f32,
    pub x2: f32,
    pub easing: Easing,
    pub y1: f32,
    pub y2: f32,
    pub color: i32,
    pub sfx: String,
    pub is_trace: bool,
    pub sky_notes: Vec<SkyNote>,
}

#[derive(Debug, Clone, Copy)]
pub struct SkyNote {
    pub time: Ms,
    pub width: f32,
}

#[derive(Debug, Clone, Copy)]
pub struct Timing {
    pub time: Ms,
    pub bpm: f32,
    pub divisor: f32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Easing {
    S,
    B,
    Si,
    So,
    SiSi,
    SiSo,
    SoSi,
    SoSo,
    SiB,
    SoB,
    BiS,
    BSi,
    BSo,
    BB,
}

impl Easing {
    /// Apply this easing to interpolate arc (x, y) at parameter t in [0, 1].
    ///
    /// Each easing type specifies independent functions for X and Y axes.
    /// Source: Ghidra -- ArcEasing (Arcaea 6.13.10c)
    pub fn apply(&self, x1: f32, x2: f32, y1: f32, y2: f32, t: f32) -> (f32, f32) {
        use std::f32::consts::FRAC_PI_2;

        let lin = |a: f32, b: f32, t: f32| (1.0 - t) * a + t * b;
        let sin_in = |a: f32, b: f32, t: f32| a + (b - a) * (FRAC_PI_2 * t).sin();
        let sin_out = |a: f32, b: f32, t: f32| a + (b - a) * (1.0 - (FRAC_PI_2 * t).cos());
        let bez = |a: f32, b: f32, t: f32| {
            let mt = 1.0 - t;
            mt * mt * mt * a + 3.0 * mt * mt * t * a + 3.0 * mt * t * t * b + t * t * t * b
        };

        match self {
            Easing::S    => (lin(x1, x2, t),     lin(y1, y2, t)),
            Easing::B    => (bez(x1, x2, t),     bez(y1, y2, t)),
            Easing::Si   => (sin_in(x1, x2, t),  lin(y1, y2, t)),
            Easing::So   => (sin_out(x1, x2, t), lin(y1, y2, t)),
            Easing::SiSi => (sin_in(x1, x2, t),  sin_in(y1, y2, t)),
            Easing::SiSo => (sin_in(x1, x2, t),  sin_out(y1, y2, t)),
            Easing::SoSi => (sin_out(x1, x2, t), sin_in(y1, y2, t)),
            Easing::SoSo => (sin_out(x1, x2, t), sin_out(y1, y2, t)),
            Easing::SiB  => (sin_in(x1, x2, t),  bez(y1, y2, t)),
            Easing::SoB  => (sin_out(x1, x2, t), bez(y1, y2, t)),
            Easing::BiS  => (bez(x1, x2, t),     lin(y1, y2, t)),
            Easing::BSi  => (bez(x1, x2, t),     sin_in(y1, y2, t)),
            Easing::BSo  => (bez(x1, x2, t),     sin_out(y1, y2, t)),
            Easing::BB   => (bez(x1, x2, t),     bez(y1, y2, t)),
        }
    }
}

