155	            bpm = Mathf.Abs(bpm);
156	            float interval = 60000f / bpm / (bpm >= 255 ? 1 : 2) / Values.TimingPointDensity;
157	            int total = (int)((to - from) / interval);
158	            if ((u ^ 1) >= total)
