// ArcFormula.cs 1:1 port
// Reference: re/ArcCreate/Assets/Scripts/Gameplay/Utility/ArcFormula.cs

use crate::chart::types::Easing;
use crate::values::*;

// === Coordinate Transforms ===

pub fn arc_x_to_world(x: f32) -> f32 {
    -LANE_WIDTH * 2.0 * x + LANE_WIDTH
}

pub fn arc_y_to_world(y: f32) -> f32 {
    ARC_Y0 + (ARC_Y1 - ARC_Y0) * y
}

pub fn world_x_to_arc(x: f32) -> f32 {
    (x - LANE_WIDTH) / -LANE_WIDTH / 2.0
}

pub fn world_y_to_arc(y: f32) -> f32 {
    (y - ARC_Y0) / (ARC_Y1 - ARC_Y0)
}

pub fn lane_to_world_x(lane: i32) -> f32 {
    -LANE_WIDTH * lane as f32 + LANE_WIDTH * 2.5
}

pub fn lane_to_world_x_f(lane: f32) -> f32 {
    -LANE_WIDTH * lane + LANE_WIDTH * 2.5
}

pub fn lane_to_arc_x(lane: i32) -> f32 {
    0.5 * lane as f32 - 0.75
}

pub fn arc_x_to_lane(x: f32) -> f32 {
    (x + 0.75) / 0.5
}

pub fn world_x_to_lane(x: f32) -> i32 {
    ((x - LANE_WIDTH * 2.5) / -LANE_WIDTH).round() as i32
}

pub fn within_render_range(z: f32) -> bool {
    z >= -TRACK_LENGTH_FORWARD && z <= TRACK_LENGTH_BACKWARD
}

// === Z / Floor Position ===

pub fn z_to_floor_position(z: f32, drop_rate: f32) -> f64 {
    z as f64 / drop_rate as f64 * base_bpm() as f64 * -1000.0
}

pub fn floor_position_to_z(fp: f64, drop_rate: f32) -> f32 {
    (fp / base_bpm() as f64 * drop_rate as f64 / -1000.0) as f32
}

// === Easing Primitives ===

fn s_ease(start: f32, end: f32, t: f32) -> f32 {
    (1.0 - t) * start + end * t
}

fn o_ease(start: f32, end: f32, t: f32) -> f32 {
    start + (end - start) * (1.0 - (1.5707963_f32 * t).cos())
}

fn i_ease(start: f32, end: f32, t: f32) -> f32 {
    start + (end - start) * (1.5707963_f32 * t).sin()
}

fn b_ease(start: f32, end: f32, t: f32) -> f32 {
    let o = 1.0 - t;
    o.powi(3) * start
        + 3.0 * o.powi(2) * t * start
        + 3.0 * o * t.powi(2) * end
        + t.powi(3) * end
}

/// Arc X interpolation — dispatches by easing type (ArcFormula.X)
pub fn arc_x(start: f32, end: f32, t: f32, easing: Easing) -> f32 {
    match easing {
        Easing::S => s_ease(start, end, t),
        Easing::B | Easing::BB => b_ease(start, end, t),
        Easing::Si | Easing::SiSi | Easing::SiSo | Easing::SiB => i_ease(start, end, t),
        Easing::So | Easing::SoSi | Easing::SoSo | Easing::SoB => o_ease(start, end, t),
        Easing::BiS | Easing::BSi | Easing::BSo => b_ease(start, end, t),
    }
}

/// Arc Y interpolation — dispatches by easing type (ArcFormula.Y)
pub fn arc_y(start: f32, end: f32, t: f32, easing: Easing) -> f32 {
    match easing {
        Easing::S | Easing::Si | Easing::So => s_ease(start, end, t),
        Easing::B | Easing::BB => b_ease(start, end, t),
        Easing::SiSi | Easing::SoSi => i_ease(start, end, t),
        Easing::SiSo | Easing::SoSo => o_ease(start, end, t),
        Easing::SiB | Easing::SoB => b_ease(start, end, t),
        Easing::BiS => s_ease(start, end, t),
        Easing::BSi => i_ease(start, end, t),
        Easing::BSo => o_ease(start, end, t),
    }
}

// === Utility Functions ===

pub fn qi(value: f32) -> f32 {
    value * value * value
}

pub fn qo(value: f32) -> f32 {
    let v = value - 1.0;
    v * v * v + 1.0
}

pub fn calculate_tap_size_scalar(z: f32) -> f32 {
    if z <= 0.0 {
        (1.5 + 6.25 * -z / TRACK_LENGTH_FORWARD).abs()
    } else {
        (1.5 + 7.25 * z / TRACK_LENGTH_BACKWARD).abs()
    }
}

pub fn calculate_beatline_size_scalar(thickness: f32, z: f32) -> f32 {
    if z <= 0.0 {
        (thickness + thickness * 3.0 * -z / TRACK_LENGTH_FORWARD).abs()
    } else {
        (thickness + thickness * 3.0 * z / TRACK_LENGTH_BACKWARD).abs()
    }
}

pub fn calculate_fade_out_alpha(z: f32) -> f32 {
    if z <= 0.0 {
        ((TRACK_LENGTH_FORWARD + z) / NOTE_FADE_OUT_LENGTH).clamp(0.0, 1.0)
    } else {
        ((TRACK_LENGTH_BACKWARD - z) / NOTE_FADE_OUT_LENGTH).clamp(0.0, 1.0)
    }
}

pub fn calculate_arc_lock_duration(arc_judge_interval: f32) -> i32 {
    (arc_judge_interval * 4.0).round().min(1000.0) as i32
}

pub fn calculate_arc_segment_length(duration: i32, arc_resolution: f32) -> f32 {
    let length = ARC_SEGMENT_LENGTH / arc_resolution;
    if duration < 1000 { length } else { length * 2.0 }
}

/// Calculate long note (hold/arc) judge timings.
/// Port of ArcFormula.CalculateLongNoteJudgeTimings.
/// `u` = 0 for holds, varies for arcs (see Arc.Judgement.cs).
pub fn calculate_long_note_judge_timings(from: i32, to: i32, bpm: f32, u: i32) -> Vec<i32> {
    let bpm_abs = bpm.abs();
    let interval = 60_000.0 / bpm_abs / (if bpm_abs >= 255.0 { 1.0 } else { 2.0 }) / timing_point_density();
    let total = ((to - from) as f32 / interval) as i32;

    let u_xor = u ^ 1;
    if u_xor >= total {
        return vec![from + ((to - from) as f32 * 0.5) as i32];
    }

    let mut result = Vec::new();
    let mut n = u_xor;
    loop {
        let t = from + (n as f32 * interval) as i32;
        if t < to {
            result.push(t);
        }
        n += 1;
        if n == total {
            break;
        }
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_coordinate_transforms_round_trip() {
        for x in [0.0_f32, 0.25, 0.5, 0.75, 1.0] {
            let world = arc_x_to_world(x);
            let back = world_x_to_arc(world);
            assert!((back - x).abs() < 1e-5, "x={x}: got {back}");
        }
        for y in [0.0_f32, 0.25, 0.5, 0.75, 1.0] {
            let world = arc_y_to_world(y);
            let back = world_y_to_arc(world);
            assert!((back - y).abs() < 1e-5, "y={y}: got {back}");
        }
    }

    #[test]
    fn test_arc_x_world_values() {
        assert!((arc_x_to_world(0.0) - 4.25).abs() < 1e-5);
        assert!((arc_x_to_world(1.0) - (-4.25)).abs() < 1e-5);
        assert!((arc_x_to_world(0.5) - 0.0).abs() < 1e-5);
    }

    #[test]
    fn test_arc_y_world_values() {
        assert!((arc_y_to_world(0.0) - 1.0).abs() < 1e-5);
        assert!((arc_y_to_world(1.0) - 5.5).abs() < 1e-5);
    }

    #[test]
    fn test_lane_to_world() {
        assert!((lane_to_world_x(1) - 6.375).abs() < 1e-3);
        assert!((lane_to_world_x(2) - 2.125).abs() < 1e-3);
        assert!((lane_to_world_x(3) - (-2.125)).abs() < 1e-3);
        assert!((lane_to_world_x(4) - (-6.375)).abs() < 1e-3);
    }

    #[test]
    fn test_easing_endpoints() {
        for easing in [
            Easing::S, Easing::B, Easing::Si, Easing::So,
            Easing::SiSi, Easing::SoSo, Easing::SiSo, Easing::SoSi,
        ] {
            assert!((arc_x(0.0, 1.0, 0.0, easing) - 0.0).abs() < 1e-5, "{easing:?} X t=0");
            assert!((arc_x(0.0, 1.0, 1.0, easing) - 1.0).abs() < 1e-5, "{easing:?} X t=1");
            assert!((arc_y(0.0, 1.0, 0.0, easing) - 0.0).abs() < 1e-5, "{easing:?} Y t=0");
            assert!((arc_y(0.0, 1.0, 1.0, easing) - 1.0).abs() < 1e-5, "{easing:?} Y t=1");
        }
    }

    #[test]
    fn test_floor_position_round_trip() {
        set_base_bpm(100.0);
        let z = -50.0_f32;
        let fp = z_to_floor_position(z, 30.0);
        let back = floor_position_to_z(fp, 30.0);
        assert!((back - z).abs() < 0.01, "z={z}, fp={fp}, back={back}");
    }

    #[test]
    fn test_fade_out_alpha() {
        assert!((calculate_fade_out_alpha(0.0) - 1.0).abs() < 1e-5);
        assert!((calculate_fade_out_alpha(-100.0) - 0.0).abs() < 1e-5);
        assert!((calculate_fade_out_alpha(-95.0) - 0.5).abs() < 1e-5);
        assert!((calculate_fade_out_alpha(53.5) - 0.0).abs() < 1e-5);
        assert!((calculate_fade_out_alpha(48.5) - 0.5).abs() < 1e-5);
    }

    #[test]
    fn test_tap_size_scalar() {
        assert!((calculate_tap_size_scalar(0.0) - 1.5).abs() < 1e-5);
        assert!(calculate_tap_size_scalar(-50.0) > 1.5);
        assert!(calculate_tap_size_scalar(26.0) > 1.5);
    }

    #[test]
    fn test_long_note_judge_timings_short() {
        set_timing_point_density(1.0);
        let result = calculate_long_note_judge_timings(0, 100, 120.0, 0);
        assert_eq!(result.len(), 1);
        assert_eq!(result[0], 50);
    }

    #[test]
    fn test_long_note_judge_timings_long() {
        set_timing_point_density(1.0);
        let result = calculate_long_note_judge_timings(0, 2000, 120.0, 0);
        assert!(result.len() > 1);
        assert!(result[0] > 0);
        for &t in &result {
            assert!(t < 2000);
        }
    }

    #[test]
    fn test_arc_lock_duration() {
        assert_eq!(calculate_arc_lock_duration(250.0), 1000);
        assert_eq!(calculate_arc_lock_duration(100.0), 400);
    }
}

