use glam::Vec3;
use std::sync::LazyLock;

pub struct MeshData {
    pub vertices: Vec<Vec3>,
    pub triangles: Vec<u32>,
}

/// Triangular prism body mesh (6 vertices, 4 triangles).
/// Used for arc segments and trace segments.
pub fn generate_body_mesh(offset: f32) -> MeshData {
    let half = offset / 2.0;
    MeshData {
        vertices: vec![
            Vec3::new(0.0, half, 0.0),        // 0: top center near
            Vec3::new(0.0, half, 1.0),        // 1: top center far
            Vec3::new(offset, -half, 1.0),    // 2: right far
            Vec3::new(offset, -half, 0.0),    // 3: right near
            Vec3::new(-offset, -half, 1.0),   // 4: left far
            Vec3::new(-offset, -half, 0.0),   // 5: left near
        ],
        triangles: vec![
            0, 3, 2,
            0, 2, 1,
            0, 1, 4,
            0, 4, 5,
        ],
    }
}

/// Pyramid head mesh (4 vertices, 2 triangles).
/// Marks the start of an arc.
pub fn generate_head_mesh(offset: f32) -> MeshData {
    let half = offset / 2.0;
    MeshData {
        vertices: vec![
            Vec3::new(0.0, half, 0.0),        // 0: top
            Vec3::new(offset, -half, 0.0),    // 1: right
            Vec3::new(0.0, -half, half),      // 2: forward
            Vec3::new(-offset, -half, 0.0),   // 3: left
        ],
        triangles: vec![
            0, 2, 1,
            0, 3, 2,
        ],
    }
}

/// Shadow mesh (flat rectangle, 4 vertices, 2 triangles).
/// Projected on the ground plane.
pub fn generate_shadow_mesh(offset: f32) -> MeshData {
    MeshData {
        vertices: vec![
            Vec3::new(offset, 0.0, 0.0),
            Vec3::new(offset, 0.0, 1.0),
            Vec3::new(-offset, 0.0, 1.0),
            Vec3::new(-offset, 0.0, 0.0),
        ],
        triangles: vec![
            0, 1, 3,
            1, 2, 3,
        ],
    }
}

// Cached mesh instances (ArcCreate caches these too)
pub static ARC_BODY: LazyLock<MeshData> = LazyLock::new(|| generate_body_mesh(crate::values::ARC_MESH_OFFSET));
pub static TRACE_BODY: LazyLock<MeshData> = LazyLock::new(|| generate_body_mesh(crate::values::TRACE_MESH_OFFSET));
pub static ARC_HEAD: LazyLock<MeshData> = LazyLock::new(|| generate_head_mesh(crate::values::ARC_MESH_OFFSET));
pub static TRACE_HEAD: LazyLock<MeshData> = LazyLock::new(|| generate_head_mesh(crate::values::TRACE_MESH_OFFSET));
pub static ARC_SHADOW: LazyLock<MeshData> = LazyLock::new(|| generate_shadow_mesh(crate::values::ARC_MESH_OFFSET));
pub static TRACE_SHADOW: LazyLock<MeshData> = LazyLock::new(|| generate_shadow_mesh(crate::values::TRACE_MESH_OFFSET));

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_body_mesh_topology() {
        let mesh = generate_body_mesh(0.9);
        assert_eq!(mesh.vertices.len(), 6);
        assert_eq!(mesh.triangles.len(), 12); // 4 triangles * 3 indices
        for &idx in &mesh.triangles {
            assert!((idx as usize) < mesh.vertices.len());
        }
    }

    #[test]
    fn test_head_mesh_topology() {
        let mesh = generate_head_mesh(0.9);
        assert_eq!(mesh.vertices.len(), 4);
        assert_eq!(mesh.triangles.len(), 6); // 2 triangles * 3 indices
        for &idx in &mesh.triangles {
            assert!((idx as usize) < mesh.vertices.len());
        }
    }

    #[test]
    fn test_shadow_mesh_flat() {
        let mesh = generate_shadow_mesh(0.9);
        assert_eq!(mesh.vertices.len(), 4);
        assert_eq!(mesh.triangles.len(), 6);
        for v in &mesh.vertices {
            assert_eq!(v.y, 0.0, "shadow must be flat on ground");
        }
    }

    #[test]
    fn test_body_mesh_symmetry() {
        let mesh = generate_body_mesh(0.9);
        // vertex 3 (right near) and vertex 5 (left near) should mirror in X
        assert!((mesh.vertices[3].x + mesh.vertices[5].x).abs() < 1e-5);
        assert!((mesh.vertices[3].y - mesh.vertices[5].y).abs() < 1e-5);
    }

    #[test]
    fn test_trace_narrower_than_arc() {
        let arc = generate_body_mesh(crate::values::ARC_MESH_OFFSET);
        let trace = generate_body_mesh(crate::values::TRACE_MESH_OFFSET);
        assert!(arc.vertices[3].x > trace.vertices[3].x);
    }

    #[test]
    fn test_cached_meshes_exist() {
        assert_eq!(ARC_BODY.vertices.len(), 6);
        assert_eq!(TRACE_BODY.vertices.len(), 6);
        assert_eq!(ARC_HEAD.vertices.len(), 4);
        assert_eq!(ARC_SHADOW.vertices.len(), 4);
    }
}

