    pub fn calculate_z(&self, current_fp: f64, drop_rate: f32) -> f32 {
        crate::gameplay::arc_formula::floor_position_to_z(
            self.floor_position - current_fp,
            drop_rate,
        )
    }

    pub fn calculate_end_z(&self, current_fp: f64, drop_rate: f32) -> f32 {
        crate::gameplay::arc_formula::floor_position_to_z(
            self.end_floor_position - current_fp,
            drop_rate,
        )
    }
}

