    pub move_y: f32,
    pub move_z: f32,
    pub rot_x: f32,
    pub rot_y: f32,
    pub rot_z: f32,
    pub easing: Easing,
    pub duration: Ms,
}

#[derive(Debug, Clone)]
pub struct SceneControl {
    pub time: Ms,
    pub kind: String,
    pub args: Vec<f32>,
}

