1	using System.Collections.Generic;
2	using ArcCreate.Gameplay.Chart;
3	using ArcCreate.Gameplay.Data;
4	using ArcCreate.Utility.Extension;
5	using UnityEngine;
6	
7	namespace ArcCreate.Gameplay.GameplayCamera
8	{
9	    public class CameraService : MonoBehaviour, ICameraService, ICameraControl
10	    {
11	        [SerializeField] private Camera backgroundCamera;
12	        [SerializeField] private Camera overlayCamera;
13	        [SerializeField] private RectTransform backgroundRect;
14	        private float currentTilt;
15	        private float currentArcPos;
16	        private bool isReset;
17	        private List<CameraEvent> events = new List<CameraEvent>();
18	
19	        private float fieldOfViewExternal;
20	        private float tiltFactorExternal;
21	        private Vector3 translationExternal;
22	        private Quaternion rotationExternal;
23	
24	        public Camera GameplayCamera => backgroundCamera;
25	
26	        public Camera UICamera => overlayCamera;
27	
28	        public List<CameraEvent> Events => events;
29	
30	        public bool IsEditorCamera { get; set; }
31	
32	        public Vector3 EditorCameraPosition { get; set; }
33	
34	        public Vector3 EditorCameraRotation { get; set; }
35	
36	        public bool IsOrthographic
37	        {
38	            get => backgroundCamera.orthographic;
39	            set
40	            {
41	                backgroundCamera.orthographic = value;
42	                overlayCamera.orthographic = value;
43	            }
44	        }
45	
46	        public float OrthographicSize
47	        {
48	            get => backgroundCamera.orthographicSize;
49	            set
50	            {
51	                backgroundCamera.orthographicSize = value;
52	                overlayCamera.orthographicSize = value;
53	            }
54	        }
55	
56	        public Camera[] RenderingCameras { get; private set; }
57	
58	        /// <summary>
59	        /// Gets 0 on 16:9, 1 on 4:3 (16:12), value is unclamped, use with Mathf.Clerp().
60	        /// </summary>
61	        private float AspectAdjustment
62	        {
63	            get
64	            {
65	                float height = backgroundCamera.pixelHeight / (backgroundCamera.pixelWidth / 16f);
66	                return (height - 9) / 3f;
67	            }
68	        }
69	
70	        private Vector3 ResetPosition
71	            => new Vector3(0f, Values.CameraY, Mathf.Lerp(Values.CameraZ, Values.CameraZTablet, AspectAdjustment));
72	
73	        private Vector3 ResetRotation
74	            => new Vector3(Mathf.Lerp(Values.CameraRotX, Values.CameraRotXTablet, AspectAdjustment), 180f, 0f);
75	
76	        private float ResetFOV
77	            => Mathf.Lerp(50, 65, AspectAdjustment);
78	
79	        public void Load(List<CameraEvent> cameras)
80	        {
81	            events = cameras;
82	            RebuildList();
83	        }
84	
85	        public void Clear()
86	        {
87	            isReset = true;
88	            events.Clear();
89	        }
90	
91	        public void Add(IEnumerable<CameraEvent> events)
92	        {
93	            this.events.AddRange(events);
94	            RebuildList();
95	        }
96	
97	        public void Change(IEnumerable<CameraEvent> events)
98	        {
99	            RebuildList();
100	        }
101	
102	        public void Remove(IEnumerable<CameraEvent> events)
103	        {
104	            foreach (var cam in events)
105	            {
106	                this.events.Remove(cam);
107	            }
108	            isReset = true;
109	            RebuildList();
110	        }
111	
112	        public void RemoveTimingGroup(TimingGroup group)
113	        {
114	            events.RemoveAll(e => e.TimingGroup == group.GroupNumber);
115	
116	            foreach (var cam in events)
117	            {
118	                if (cam.TimingGroup > group.GroupNumber)
119	                {
120	                    cam.TimingGroup -= 1;
121	                    cam.ResetTimingGroupChangedFrom();
122	                }
123	            }
124	
125	            RebuildList();
126	        }
127	
128	        public void InsertTimingGroup(TimingGroup group)
129	        {
130	            foreach (var cam in events)
131	            {
132	                if (cam.TimingGroup >= group.GroupNumber)
133	                {
134	                    cam.TimingGroup += 1;
135	                    cam.ResetTimingGroupChangedFrom();
136	                }
137	            }
138	
139	            RebuildList();
140	        }
141	
142	        public IEnumerable<CameraEvent> FindByTiming(int from, int to)
143	        {
144	            for (int i = 0; i < events.Count; i++)
145	            {
146	                CameraEvent cam = events[i];
147	                if (cam.Timing >= from && cam.Timing >= from && cam.Timing <= to)
148	                {
149	                    yield return cam;
150	                }
151	            }
152	        }
153	
154	        public IEnumerable<CameraEvent> FindWithinRange(int from, int to, bool overlapCompletely)
155	        {
156	            for (int i = 0; i < events.Count; i++)
157	            {
158	                CameraEvent cam = events[i];
159	                if ((overlapCompletely && cam.Timing >= from && cam.Timing + cam.Duration <= to)
160	                 || (!overlapCompletely && (cam.Timing >= from || cam.Timing + cam.Duration <= to)))
161	                {
162	                    yield return cam;
163	                }
164	            }
165	        }
166	
167	        public void AddTiltToCamera(float arcWorldX)
168	        {
169	            currentArcPos += arcWorldX;
170	        }
171	
172	        public void SetPropertiesExternal(float fieldOfView, float tiltFactor)
173	        {
174	            fieldOfViewExternal = fieldOfView;
175	            tiltFactorExternal = tiltFactor;
176	        }
177	
178	        public void SetTransformExternal(Vector3 translation, Quaternion rotation)
179	        {
180	            translationExternal = translation;
181	            rotationExternal = rotation;
182	        }
183	
184	        public void UpdateCamera(int currentTiming)
185	        {
186	            UpdateBackgroundCanvas();
187	            if (IsEditorCamera)
188	            {
189	                GameplayCamera.transform.localPosition = EditorCameraPosition;
190	                GameplayCamera.transform.localRotation = Quaternion.Euler(EditorCameraRotation);
191	                return;
192	            }
193	
194	            Vector3 prevPosition = backgroundCamera.transform.localPosition;
195	            Vector3 position = ResetPosition + translationExternal;
196	            Quaternion lookAtRotation = Quaternion.LookRotation(
197	                new Vector3(0, -5.5f, -20) - ResetPosition,
198	                new Vector3(currentTilt, 1 - currentTilt, 0)) * Quaternion.Inverse(Quaternion.Euler(ResetRotation));
199	            float fov = ResetFOV + fieldOfViewExternal;
200	            Vector3 rotation = ResetRotation;
201	            backgroundCamera.fieldOfView = fov;
202	            overlayCamera.fieldOfView = fov;
203	
204	            isReset = true;
205	            for (int i = 0; i < events.Count; i++)
206	            {
207	                CameraEvent cam = events[i];
208	                if (cam.Timing > currentTiming)
209	                {
210	                    break;
211	                }
212	
213	                isReset = cam.IsReset;
214	                if (isReset)
215	                {
216	                    position = ResetPosition + translationExternal;
217	                    rotation = ResetRotation;
218	                }
219	
220	                float percent = cam.PercentAt(currentTiming);
221	                position += new Vector3(-cam.Move.x, cam.Move.y, cam.Move.z) * percent / 100f;
222	                rotation += new Vector3(-cam.Rotate.y, -cam.Rotate.x, cam.Rotate.z) * percent;
223	            }
224	
225	            if (position.IsNaN() || rotation.IsNaN())
226	            {
227	                backgroundCamera.transform.localPosition = prevPosition;
228	            }
229	            else
230	            {
231	                backgroundCamera.transform.localPosition = position;
232	                backgroundCamera.transform.localRotation = lookAtRotation * rotationExternal * Quaternion.Euler(0f, 0f, rotation.z) * Quaternion.Euler(rotation.x, rotation.y, 0f);
233	            }
234	
235	            UpdateCameraTilt();
236	        }
237	
238	        public float CalculateDepthSquared(Vector3 fromPos)
239	        {
240	            return (backgroundCamera.transform.localPosition - fromPos).sqrMagnitude;
241	        }
242	
243	        private void UpdateBackgroundCanvas()
244	        {
245	            backgroundRect.pivot = new Vector2(0.5f, Mathf.Lerp(0.87f, 0.5f, AspectAdjustment));
246	            backgroundRect.anchorMin = new Vector2(0.5f, Mathf.Lerp(1f, 0.5f, AspectAdjustment));
247	            backgroundRect.anchorMax = new Vector2(0.5f, Mathf.Lerp(1f, 0.5f, AspectAdjustment));
248	        }
249	
250	        private void UpdateCameraTilt()
251	        {
252	            if (!isReset)
253	            {
254	                currentTilt = 0;
255	                return;
256	            }
257	
258	            float pos = -Mathf.Clamp(currentArcPos / Values.LaneWidth, -1, 1) * Values.CameraArcPosScalar;
259	            float delta = pos - currentTilt;
260	            if (Mathf.Abs(delta) >= 0.001f)
261	            {
262	                float speed = Values.CameraTiltSpeed;
263	                float deltaTime = Mathf.Min(Time.deltaTime, 0.1f);
264	                currentTilt += speed * delta * deltaTime;
265	            }
266	            else
267	            {
268	                currentTilt = pos;
269	            }
270	
271	            currentTilt *= tiltFactorExternal;
272	            currentArcPos = 0;
273	        }
274	
275	        private void RebuildList()
276	        {
277	            events.Sort((a, b) => a.CompareTo(b));
278	        }
279	
280	        private void Awake()
281	        {
282	            currentArcPos = 0;
283	            isReset = true;
284	            RenderingCameras = new Camera[] { backgroundCamera, overlayCamera };
285	        }
286	    }
287	}

