// ArcCreate Track.shader port
// Reference: re/ArcCreate/Assets/Shaders/Track.shader
// Per-lane alpha control + UV pattern modification

struct CameraUniform {
    view_proj: mat4x4<f32>,
}

struct TrackUniforms {
    color: vec4<f32>,
    modify: vec4<f32>,         // (offset_x, offset_y, scale_x, scale_y)
    uv_offset: f32,            // _Offset — vertical UV scroll
    edge_l_alpha: f32,
    lane1_alpha: f32,
    lane2_alpha: f32,
    lane3_alpha: f32,
    lane4_alpha: f32,
    edge_r_alpha: f32,
    // Lane boundary UV.x thresholds
    boundary_l1: f32,
    boundary_12: f32,
    boundary_23: f32,
    boundary_34: f32,
    boundary_4r: f32,
}

