// Shared structures for instanced rendering shaders.
// Each shader includes this via copy (WGSL has no #include).
// This file exists as documentation — actual structs are duplicated per shader.

// Vertex input (from MeshVertex buffer, step_mode=Vertex):
//   @location(0) position: vec3<f32>
//   @location(1) uv: vec2<f32>

// Instance input (from InstanceData buffer, step_mode=Instance):
//   @location(2-5) model: mat4x4<f32>  (4 columns)
//   @location(6) color: vec4<f32>
//   @location(7) properties: vec4<f32>  (shader-specific)
//     .x = selected (0 or 1)
//     .y = highlight (0 or 1)
//     .z = from (0-1 clip parameter, for holds)
//     .w = reserved

// Bind groups:
//   @group(0) camera uniform (view_proj mat4)
//   @group(1) texture + sampler

