// Shadow rendering with per-corner offset displacement

struct CameraUniform { view_proj: mat4x4<f32> }
@group(0) @binding(0) var<uniform> camera: CameraUniform;
@group(1) @binding(0) var tex: texture_2d<f32>;
@group(1) @binding(1) var tex_sampler: sampler;

struct VsIn {
    @location(0) position: vec3<f32>,
    @location(1) uv: vec2<f32>,
    @location(2) model_0: vec4<f32>,
    @location(3) model_1: vec4<f32>,
    @location(4) model_2: vec4<f32>,
    @location(5) model_3: vec4<f32>,
    @location(6) color: vec4<f32>,
    @location(7) properties: vec4<f32>, // .x = corner_offset
}

struct VsOut {
    @builtin(position) clip_position: vec4<f32>,
    @location(0) color: vec4<f32>,
    @location(1) uv: vec2<f32>,
}

@vertex
fn vs_main(in: VsIn) -> VsOut {
    let model = mat4x4<f32>(in.model_0, in.model_1, in.model_2, in.model_3);

    // Per-corner offset displacement (ArcCreate Shadow.shader _Offset)
    // UV quadrant determines which corners get offset
    let corner_offset = in.properties.x;
    var pos = in.position;
    // Front-right and front-left corners get displaced
    if in.uv.y > 0.5 {
        if in.uv.x > 0.5 {
            pos.x = pos.x + corner_offset;
        } else {
            pos.x = pos.x - corner_offset;
        }
    }

    let world_pos = model * vec4<f32>(pos, 1.0);
    var out: VsOut;
    out.clip_position = camera.view_proj * world_pos;
    out.color = in.color;
    out.color.a = out.color.a * 0.7; // fixed shadow alpha
    out.uv = in.uv;
    return out;
}

@fragment
fn fs_main(in: VsOut) -> @location(0) vec4<f32> {
    let tex_color = textureSample(tex, tex_sampler, in.uv);
    return tex_color * in.color;
}

