// ArcCreate RenderService port
// Reference: re/ArcCreate/Assets/Scripts/Gameplay/Render/RenderService.cs
// Draw call queuing, depth sorting, 14-layer render order

use crate::render::instanced::{InstancedRenderer, SortedDrawer};
use crate::render::vertex::InstanceData;

/// Central render coordinator. Collects draw calls per frame,
/// sorts arc/trace by depth, and renders in ArcCreate's 14-layer order.
pub struct RenderService {
    // Per-type drawers
    pub hold_drawer: InstancedRenderer,
    pub connection_line_drawer: InstancedRenderer,
    pub tap_drawer: InstancedRenderer,
    pub trace_shadow_drawer: InstancedRenderer,
    pub arc_shadow_drawer: InstancedRenderer,
    pub trace_segment_sorted: SortedDrawer,
    pub trace_segment_drawer: InstancedRenderer,
    pub trace_head_drawer: InstancedRenderer,
    pub arctap_shadow_drawer: InstancedRenderer,
    pub height_indicator_drawer: InstancedRenderer,
    pub arc_cap_drawer: InstancedRenderer,
    pub arc_segment_sorted: SortedDrawer,
    pub arc_segment_drawer: InstancedRenderer,
    pub arctap_drawer: InstancedRenderer,
    pub arctap_sfx_drawer: InstancedRenderer,
    pub arc_head_drawer: InstancedRenderer,
    pub beatline_drawer: InstancedRenderer,
    pub particle_drawer: InstancedRenderer,
}

/// Pipeline handles for each shader type.
pub struct Pipelines {
    pub track: wgpu::RenderPipeline,
    pub tap_note: wgpu::RenderPipeline,
    pub hold_note: wgpu::RenderPipeline,
    pub arc: wgpu::RenderPipeline,
    pub trace: wgpu::RenderPipeline,
    pub shadow: wgpu::RenderPipeline,
    pub arc_tap: wgpu::RenderPipeline,
    pub single_line: wgpu::RenderPipeline, // additive blend
    pub height_indicator: wgpu::RenderPipeline,
    pub instanced_sprite: wgpu::RenderPipeline,
}

impl RenderService {
    pub fn clear_all(&mut self) {
        self.hold_drawer.clear();
        self.connection_line_drawer.clear();
        self.tap_drawer.clear();
        self.trace_shadow_drawer.clear();
        self.arc_shadow_drawer.clear();
        self.trace_segment_sorted.clear();
        self.trace_segment_drawer.clear();
        self.trace_head_drawer.clear();
        self.arctap_shadow_drawer.clear();
        self.height_indicator_drawer.clear();
        self.arc_cap_drawer.clear();
        self.arc_segment_sorted.clear();
        self.arc_segment_drawer.clear();
        self.arctap_drawer.clear();
        self.arctap_sfx_drawer.clear();
        self.arc_head_drawer.clear();
        self.beatline_drawer.clear();
        self.particle_drawer.clear();
    }

    /// Sort arc/trace segments by depth and flush to their renderers.
    pub fn flush_sorted(&mut self) {
        self.trace_segment_sorted.flush(&mut self.trace_segment_drawer);
        self.arc_segment_sorted.flush(&mut self.arc_segment_drawer);
    }

    /// Upload all instance buffers to GPU.
    pub fn upload_all(&mut self, device: &wgpu::Device, queue: &wgpu::Queue) {
        self.hold_drawer.upload(device, queue);
        self.connection_line_drawer.upload(device, queue);
        self.tap_drawer.upload(device, queue);
        self.trace_shadow_drawer.upload(device, queue);
        self.arc_shadow_drawer.upload(device, queue);
        self.trace_segment_drawer.upload(device, queue);
        self.trace_head_drawer.upload(device, queue);
        self.arctap_shadow_drawer.upload(device, queue);
        self.height_indicator_drawer.upload(device, queue);
        self.arc_cap_drawer.upload(device, queue);
        self.arc_segment_drawer.upload(device, queue);
        self.arctap_drawer.upload(device, queue);
        self.arctap_sfx_drawer.upload(device, queue);
        self.arc_head_drawer.upload(device, queue);
        self.beatline_drawer.upload(device, queue);
        self.particle_drawer.upload(device, queue);
    }

    // === Draw call convenience methods (used by gameplay note code) ===

    pub fn draw_tap(&mut self, instance: InstanceData) {
        self.tap_drawer.add(instance);
    }

    pub fn draw_hold(&mut self, instance: InstanceData) {
        self.hold_drawer.add(instance);
    }

    pub fn draw_arc_segment(&mut self, instance: InstanceData, depth: f32) {
        self.arc_segment_sorted.add(instance, depth);
    }

    pub fn draw_trace_segment(&mut self, instance: InstanceData, depth: f32) {
        self.trace_segment_sorted.add(instance, depth);
    }

    pub fn draw_arc_head(&mut self, instance: InstanceData) {
        self.arc_head_drawer.add(instance);
    }

    pub fn draw_trace_head(&mut self, instance: InstanceData) {
        self.trace_head_drawer.add(instance);
    }

    pub fn draw_arc_shadow(&mut self, instance: InstanceData) {
        self.arc_shadow_drawer.add(instance);
    }

    pub fn draw_trace_shadow(&mut self, instance: InstanceData) {
        self.trace_shadow_drawer.add(instance);
    }

    pub fn draw_arc_cap(&mut self, instance: InstanceData) {
        self.arc_cap_drawer.add(instance);
    }

    pub fn draw_arctap(&mut self, instance: InstanceData, is_sfx: bool) {
        if is_sfx {
            self.arctap_sfx_drawer.add(instance);
        } else {
            self.arctap_drawer.add(instance);
        }
    }

    pub fn draw_arctap_shadow(&mut self, instance: InstanceData) {
        self.arctap_shadow_drawer.add(instance);
    }

    pub fn draw_height_indicator(&mut self, instance: InstanceData) {
        self.height_indicator_drawer.add(instance);
    }

    pub fn draw_connection_line(&mut self, instance: InstanceData) {
        self.connection_line_drawer.add(instance);
    }

    pub fn draw_beatline(&mut self, instance: InstanceData) {
        self.beatline_drawer.add(instance);
    }

    pub fn draw_particle(&mut self, instance: InstanceData) {
        self.particle_drawer.add(instance);
    }

    /// Encode the render pass in ArcCreate's 14-layer order.
    /// Call after flush_sorted() and upload_all().
    pub fn encode_render_pass<'a>(
        &'a self,
        pass: &mut wgpu::RenderPass<'a>,
        pipelines: &'a Pipelines,
        camera_bg: &'a wgpu::BindGroup,
        textures: &'a DrawTextures,
    ) {
        // 1. Holds
        self.hold_drawer.draw(pass, &pipelines.hold_note, camera_bg, &textures.hold);
        // 2. Connection lines
        self.connection_line_drawer.draw(pass, &pipelines.instanced_sprite, camera_bg, &textures.connection);
        // 3. Taps
        self.tap_drawer.draw(pass, &pipelines.tap_note, camera_bg, &textures.tap);
        // 4. Trace shadows
        self.trace_shadow_drawer.draw(pass, &pipelines.shadow, camera_bg, &textures.shadow);
        // 5. Arc shadows
        self.arc_shadow_drawer.draw(pass, &pipelines.shadow, camera_bg, &textures.shadow);
        // 6. Sorted trace segments
        self.trace_segment_drawer.draw(pass, &pipelines.trace, camera_bg, &textures.arc_body);
        // 7. Trace heads
        self.trace_head_drawer.draw(pass, &pipelines.trace, camera_bg, &textures.arc_body);
        // 8. ArcTap shadows
        self.arctap_shadow_drawer.draw(pass, &pipelines.shadow, camera_bg, &textures.shadow);
        // 9. Height indicators
        self.height_indicator_drawer.draw_no_texture(pass, &pipelines.height_indicator, camera_bg);
        // 10. Arc caps
        self.arc_cap_drawer.draw(pass, &pipelines.instanced_sprite, camera_bg, &textures.arc_cap);
        // 11. Sorted arc segments
        self.arc_segment_drawer.draw(pass, &pipelines.arc, camera_bg, &textures.arc_body);
        // 12. ArcTaps (normal)
        self.arctap_drawer.draw(pass, &pipelines.arc_tap, camera_bg, &textures.arctap);
        // 13. ArcTaps (SFX)
        self.arctap_sfx_drawer.draw(pass, &pipelines.arc_tap, camera_bg, &textures.arctap_sfx);
        // 14. Arc heads
