pub struct DrawTextures {
    pub tap: wgpu::BindGroup,
    pub hold: wgpu::BindGroup,
    pub arc_body: wgpu::BindGroup,
    pub arc_cap: wgpu::BindGroup,
    pub arctap: wgpu::BindGroup,
    pub arctap_sfx: wgpu::BindGroup,
    pub shadow: wgpu::BindGroup,
    pub connection: wgpu::BindGroup,
    pub beatline: wgpu::BindGroup,
    pub particle: wgpu::BindGroup,
}

