// ArcCreate Tap.cs UpdateRender port
// Reference: re/ArcCreate/Assets/Scripts/Gameplay/Data/Events/Tap.cs

use glam::{Mat4, Quat, Vec3, Vec4};
use crate::chart::types::{Tap, GroupProperties, Ms};
use crate::gameplay::arc_formula;
use crate::render::render_service::RenderService;
use crate::render::vertex::InstanceData;

/// Runtime state for a tap note during gameplay.
pub struct TapState {
    pub is_hit: bool,
    pub is_selected: bool,
}

impl Default for TapState {
    fn default() -> Self {
        Self { is_hit: false, is_selected: false }
    }
}

/// Update rendering for a single tap note.
/// Returns true if the note was drawn.
pub fn update_render(
    tap: &Tap,
    state: &TapState,
    floor_position: f64,
    current_fp: f64,
    drop_rate: f32,
    props: &GroupProperties,
    render: &mut RenderService,
) -> bool {
    if state.is_hit && !props.no_clip {
        return false;
    }

    let z = arc_formula::floor_position_to_z(floor_position - current_fp, drop_rate);
    if !arc_formula::within_render_range(z) {
        return false;
    }

    let base_pos = Vec3::new(arc_formula::lane_to_world_x_f(tap.lane), 0.0, 0.0);
    let pos = props.fall_direction * z + base_pos;
    let rot = props.rotation_individual;
    let mut scl = props.scale_individual;
    scl.z *= arc_formula::calculate_tap_size_scalar(z);

    let matrix = props.group_matrix * Mat4::from_scale_rotation_translation(scl, rot, pos);

    let alpha = arc_formula::calculate_fade_out_alpha(z);
    let mut color = props.color;
    color.w *= alpha;

    let selected = if state.is_selected { 1.0 } else { 0.0 };
    render.draw_tap(InstanceData::new(
        matrix,
        color.into(),
        [selected, 0.0, 0.0, 0.0],
    ));

    true
}

/// Update rendering for connection lines from a tap to its connected arctaps.
pub fn draw_connection_lines(
    tap: &Tap,
    connected_arctap_positions: &[(f32, f32)], // (world_x, world_y) of each arctap
    floor_position: f64,
    current_fp: f64,
    drop_rate: f32,
    props: &GroupProperties,
    render: &mut RenderService,
) {
    if props.no_connection || connected_arctap_positions.is_empty() {
        return;
    }

    let z = arc_formula::floor_position_to_z(floor_position - current_fp, drop_rate);
    let base_pos = Vec3::new(arc_formula::lane_to_world_x_f(tap.lane), 0.0, 0.0);
    let alpha = arc_formula::calculate_fade_out_alpha(z);

    for &(ax, ay) in connected_arctap_positions {
        let arctap_pos = Vec3::new(ax, ay - 0.2, 0.0);
        let direction = arctap_pos - base_pos;
        let length = direction.length();
        if length < 0.001 {
            continue;
        }

        let forward = direction / length;
        let look_rot = Quat::from_rotation_arc(Vec3::Z, forward);

        let tap_matrix = props.group_matrix
            * Mat4::from_scale_rotation_translation(props.scale_individual, props.rotation_individual, props.fall_direction * z + base_pos);

        let line_matrix = tap_matrix
            * Mat4::from_scale_rotation_translation(Vec3::new(1.0, 1.0, length), look_rot, Vec3::ZERO);

        let mut color = props.color;
        color.w *= alpha;
        render.draw_connection_line(InstanceData::new(
            line_matrix,
            color.into(),
            [0.0; 4],
        ));
    }
}

