use glam::{Mat4, Vec3, Vec4};
use crate::chart::types::{Hold, GroupProperties, Ms};
use crate::gameplay::arc_formula;
use crate::values::*;
use crate::render::render_service::RenderService;
use crate::render::vertex::InstanceData;

/// Runtime state for a hold note during gameplay.
pub struct HoldState {
    pub locked: bool,           // true until initial tap judgment unlocks
    pub highlight: bool,        // true while being held
    pub flash_count: i32,       // cycles for flash animation
    pub is_selected: bool,
    pub long_particle_until: i32,
}

impl Default for HoldState {
    fn default() -> Self {
        Self {
            locked: true,
            highlight: false,
            flash_count: 0,
            is_selected: false,
            long_particle_until: i32::MIN,
        }
    }
}

/// Construct a shear matrix that replaces the Z column.
/// Port of ArcCreate MatrixUtility.Shear(Vector3 dir).
fn shear_matrix(dir: Vec3) -> Mat4 {
    Mat4::from_cols(
        Vec4::new(1.0, 0.0, 0.0, 0.0),
        Vec4::new(0.0, 1.0, 0.0, 0.0),
        Vec4::new(dir.x, dir.y, dir.z, 0.0),
        Vec4::new(0.0, 0.0, 0.0, 1.0),
    )
}

/// Update rendering for a single hold note.
/// Returns true if the note was drawn.
pub fn update_render(
    hold: &Hold,
    state: &mut HoldState,
    floor_position: f64,
    end_floor_position: f64,
    current_timing: Ms,
    current_fp: f64,
    drop_rate: f32,
    props: &GroupProperties,
    render: &mut RenderService,
) -> bool {
    let z = arc_formula::floor_position_to_z(floor_position - current_fp, drop_rate);
    let mut clip_z = z;

    // Clip: once the hold is active (past start timing), render from judgment line
    if (!state.locked || props.no_input) && !props.no_clip {
        if hold.start <= current_timing {
            clip_z = 0.0;
        }

        // Past end → don't render
        let progress = if end_floor_position != floor_position {
            (current_fp - floor_position) / (end_floor_position - floor_position)
        } else {
            1.0
        };
        if progress > 1.0 {
            return false;
        }
    }

    let end_z = arc_formula::floor_position_to_z(end_floor_position - current_fp, drop_rate);

    let pos = props.fall_direction * clip_z + Vec3::new(arc_formula::lane_to_world_x_f(hold.lane), 0.0, 0.0);
    let rot = props.rotation_individual;
    let scl = props.scale_individual;

    let matrix = props.group_matrix
        * Mat4::from_scale_rotation_translation(scl, rot, pos)
        * shear_matrix(props.fall_direction * (clip_z - end_z));

    // Alpha calculation
    let mut alpha = 1.0_f32;
    if state.highlight {
        state.flash_count = (state.flash_count + 1) % HOLD_FLASH_CYCLE;
        if state.flash_count == 0 {
            alpha = FLASH_HOLD_ALPHA_SCALAR;
        }
    } else if current_timing >= hold.start {
        if props.fading_holds {
            let last_hit = state.long_particle_until.max(hold.start);
            let t = (current_timing - last_hit - FADING_HOLDS_FADE_DELAY) as f32
                / FADING_HOLDS_FADE_DURATION as f32;
            alpha = lerp(1.0, MISSED_HOLD_ALPHA_SCALAR, t.clamp(0.0, 1.0));
        } else {
            alpha = MISSED_HOLD_ALPHA_SCALAR;
        }
    }
    alpha *= MAX_HOLD_ALPHA;

    let mut color = props.color;
    color.w *= alpha;

    let selected = if state.is_selected { 1.0 } else { 0.0 };
    let highlight_f = if state.highlight { 1.0 } else { 0.0 };
    render.draw_hold(InstanceData::new(
        matrix,
        color.into(),
        [selected, highlight_f, 0.0, 0.0],
    ));

    true
}

fn lerp(a: f32, b: f32, t: f32) -> f32 {
    a + (b - a) * t
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_shear_matrix_identity_direction() {
        let m = shear_matrix(Vec3::new(0.0, 0.0, 1.0));
        assert_eq!(m, Mat4::IDENTITY);
    }

    #[test]
    fn test_shear_matrix_custom() {
        let m = shear_matrix(Vec3::new(1.0, 2.0, 3.0));
        let p = m * Vec4::new(0.0, 0.0, 1.0, 1.0);
        assert!((p.x - 1.0).abs() < 1e-5);
        assert!((p.y - 2.0).abs() < 1e-5);
        assert!((p.z - 3.0).abs() < 1e-5);
    }
}

