150	        public void UpdateRender(int currentTiming, double currentFloorPosition, GroupProperties groupProperties)
151	        {
152	            float z = ZPos(currentFloorPosition);
153	
154	            Vector3 basePos = new Vector3(ArcFormula.ArcXToWorld(XStart), ArcFormula.ArcYToWorld(YStart), 0);
155	            Vector3 pos = (groupProperties.FallDirection * z) + basePos;
156	            Quaternion rot = groupProperties.RotationIndividual;
157	            Vector3 scl = groupProperties.ScaleIndividual;
158	            Matrix4x4 matrix = groupProperties.GroupMatrix * Matrix4x4.TRS(pos, rot, scl);
159	
160	            float alpha = 1;
161	            float redArcValue = Services.Skin.GetRedArcValue(Color);
162	            if (!IsTrace)
163	            {
164	                if (highlight)
165	                {
166	                    flashCount = (flashCount + 1) % Values.ArcFlashCycle;
167	                    if (flashCount == 0)
168	                    {
169	                        alpha = Values.FlashArcAlphaScalar;
170	                    }
171	
172	                    if (currentTiming >= Timing && currentTiming <= EndTiming)
173	                    {
174	                        Services.Camera.AddTiltToCamera(WorldXAt(currentTiming));
175	                    }
176	                }
177	                else
178	                {
179	                    if (currentTiming >= (firstArcOfBranch?.Timing ?? Timing))
180	                    {
181	                        alpha = Values.MissedArcAlphaScalar;
182	                    }
183	                }
184	
185	                alpha *= Values.MaxArcAlpha;
186	            }
187	
188	            Color color = groupProperties.Color;
189	            color.a *= Mathf.Min(alpha, arcGroupAlpha);
190	
191	            int clipToTiming;
192	            double clipToFloorPosition;
193	            if (hasBeenHitOnce || IsTrace || groupProperties.NoInput || Timing == EndTiming)
194	            {
195	                clipToTiming = currentTiming;
196	                clipToFloorPosition = currentFloorPosition;
197	            }
198	            else
199	            {
200	                clipToTiming = Timing;
201	                clipToFloorPosition = FloorPosition;
202	            }
203	
204	            var (shouldDrawArcCap, arcCapMatrix, arcCapColor) = UpdateSegmentsAndArcCap(
205	                currentTiming,
206	                currentFloorPosition,
207	                clipToTiming,
208	                clipToFloorPosition,
209	                groupProperties.FallDirection,
210	                z,
211	                groupProperties.NoClip);
212	
213	            for (int i = 0; i < segments.Count; i++)
214	            {
215	                ArcSegmentData segment = segments[i];
216	                float from = segment.From;
217	                float zPos = segment.CalculateZPos(currentFloorPosition);
218	                float endZPos = segment.CalculateEndZPos(currentFloorPosition);
219	                if (from > 1
220	                 || (zPos < -Values.TrackLengthForward && endZPos < -Values.TrackLengthForward)
221	                 || (zPos > Values.TrackLengthBackward && endZPos > Values.TrackLengthBackward)
222	                 || (Timing != EndTiming && zPos == endZPos))
223	                {
224	                    continue;
225	                }
226	
227	                Vector3 midpoint = pos + ((segment.StartPosition + segment.EndPosition) / 2);
228	                midpoint.z = (zPos + endZPos) / 2;
229	                float depth = Services.Camera.CalculateDepthSquared(midpoint);
230	
231	                var (bodyMatrix, shadowMatrix, cornerOffset) =
232	                        (EndTiming > Timing || IsTrace) ?
233	                        segment.GetMatrices(currentFloorPosition, groupProperties.FallDirection, z, pos.y) :
234	                        segment.GetMatricesSlam(
235	                            currentFloorPosition,
236	                            groupProperties.FallDirection,
237	                            z,
238	                            pos,
239	                            TimingGroupInstance,
240	                            NextArc,
241	                            Values.ArcMeshOffset);
242	
243	                if (IsTrace)
244	                {
245	                    Services.Render.DrawTraceSegment(matrix * bodyMatrix, color, IsSelected, depth);
246	                    if (!groupProperties.NoShadow)
247	                    {
248	                        Services.Render.DrawTraceShadow(matrix * shadowMatrix, color);
249	                    }
250	                }
251	                else
252	                {
253	                    Services.Render.DrawArcSegment(Color, highlight, matrix * bodyMatrix, color, IsSelected, redArcValue, basePos.y + segment.EndPosition.y, depth);
254	                    if (!groupProperties.NoShadow)
255	                    {
256	                        Services.Render.DrawArcShadow(matrix * shadowMatrix, color, cornerOffset);
257	                    }
258	                }
259	            }
260	
261	            if (!groupProperties.NoHeightIndicator && (clipToTiming <= Timing || groupProperties.NoClip) && ShouldDrawHeightIndicator)
262	            {
263	                Matrix4x4 heightIndicatorMatrix = Matrix4x4.Scale(new Vector3(1, pos.y - (Values.TraceMeshOffset / 2), 1));
264	                Services.Render.DrawHeightIndicator(matrix * heightIndicatorMatrix, heightIndicatorColor * groupProperties.Color);
265	            }
266	
267	            if (!groupProperties.NoHead && (clipToTiming <= Timing || groupProperties.NoClip) && IsFirstArcOfGroup)
268	            {
269	                if (IsTrace)
270	                {
271	                    Services.Render.DrawTraceHead(matrix, color, IsSelected);
272	                }
273	                else
274	                {
275	                    Services.Render.DrawArcHead(Color, highlight, matrix, color, IsSelected, redArcValue, basePos.y + segments[0].EndPosition.y);
276	                }
277	            }
278	
279	            if (!groupProperties.NoArcCap && shouldDrawArcCap)
280	            {
281	                Services.Render.DrawArcCap(arcCap, matrix * arcCapMatrix, arcCapColor * groupProperties.Color, isControllerMode);
282	            }
283	
284	            if (currentTiming <= longParticleUntil && currentTiming >= Timing && currentTiming <= EndTiming)
285	            {
286	                Services.Particle.PlayArcParticle(
287	                    Color,
288	                    firstArcOfBranch ?? this,
289	                    WorldSegmentedPosAt(currentTiming) + groupProperties.CurrentJudgementOffset);
290	            }
291	        }
