360	        public float WorldSegmentedXAt(int timing)
361	        {
362	            for (int i = 0; i < segments.Count; i++)
363	            {
364	                var seg = segments[i];
365	                if (seg.Timing <= timing && timing <= seg.EndTiming)
366	                {
367	                    if (seg.Timing == seg.EndTiming)
368	                    {
369	                        return seg.StartPosition.x + ArcFormula.ArcXToWorld(XStart);
370	                    }
371	
372	                    float dx = (seg.EndPosition - seg.StartPosition).x;
373	                    float dt = (float)(timing - seg.Timing) / (seg.EndTiming - seg.Timing);
374	                    return seg.StartPosition.x + (dt * dx) + ArcFormula.ArcXToWorld(XStart);
375	                }
376	            }
377	
378	            return WorldXAt(timing);
379	        }
380	
381	        public Vector3 WorldSegmentedPosAt(int timing)
382	        {
383	            for (int i = 0; i < segments.Count; i++)
384	            {
385	                var seg = segments[i];
386	                if (seg.Timing <= timing && timing <= seg.EndTiming)
387	                {
388	                    var xStart = ArcFormula.ArcXToWorld(XStart);
389	                    var yStart = ArcFormula.ArcYToWorld(YStart);
390	                    var xSegStart = seg.StartPosition.x;
391	                    var ySegStart = seg.StartPosition.y;
392	                    if (seg.Timing == seg.EndTiming)
393	                    {
394	                        var sx = xSegStart + xStart;
395	                        var sy = ySegStart + yStart;
396	                        return new Vector3(sx, sy);
397	                    }
398	
399	                    Vector3 dv = (seg.EndPosition - seg.StartPosition);
400	                    float dx = dv.x;
401	                    float dy = dv.y;
402	                    float dt = (float)(timing - seg.Timing) / (seg.EndTiming - seg.Timing);
403	                    var x = xSegStart + (dt * dx) + xStart;
404	                    var y = ySegStart + (dt * dy) + yStart;
405	                    return new Vector3(x, y);
406	                }
407	            }
408	
409	            return new Vector3(WorldXAt(timing), WorldYAt(timing));
410	        }
411	
412	        private void RebuildSegments()
413	        {
414	            if (Values.EnableArcRebuildSegment || segments.Count == 0)
415	            {
416	                int lastEndTiming = Timing;
417	                double lastEndFloorPosition = TimingGroupInstance.GetFloorPosition(Timing);
418	                Vector2 basePosition = new Vector2(ArcFormula.ArcXToWorld(XStart), ArcFormula.ArcYToWorld(YStart));
419	                Vector2 lastPosition = basePosition;
420	                int finalTiming = EndTiming;
421	                Vector2 finalPosition = new Vector2(ArcFormula.ArcXToWorld(XEnd), ArcFormula.ArcYToWorld(YEnd));
422	                if (NextArc != null)
423	                {
424	                    finalTiming = NextArc.Timing;
425	                    finalPosition = new Vector2(ArcFormula.ArcXToWorld(NextArc.XStart), ArcFormula.ArcYToWorld(NextArc.YStart));
426	                }
427	
428	                int i = 0;
429	                while (true)
430	                {
431	                    int timing = lastEndTiming;
432	                    int endTiming = timing + Mathf.RoundToInt(SegmentLength);
433	                    int cappedEndTiming = Mathf.Min(endTiming, finalTiming);
434	
435	                    ArcSegmentData segment = i < segments.Count ? segments[i] : default;
436	                    if (i >= segments.Count)
437	                    {
438	                        segments.Add(segment);
439	                    }
440	
441	                    segment.Timing = timing;
442	                    segment.EndTiming = cappedEndTiming;
443	                    segment.TimingGroup = TimingGroup;
444	                    segment.FloorPosition = lastEndFloorPosition;
445	                    segment.StartPosition = lastPosition - basePosition;
446	
447	                    lastEndFloorPosition = TimingGroupInstance.GetFloorPosition(cappedEndTiming);
448	                    segment.EndFloorPosition = lastEndFloorPosition;
449	                    lastPosition = cappedEndTiming == finalTiming ?
450	                        finalPosition :
451	                        new Vector2(WorldXAt(cappedEndTiming), WorldYAt(cappedEndTiming));
452	                    segment.EndPosition = lastPosition - basePosition;
453	                    segment.From = 0;
454	
455	                    segments[i] = segment;
456	
457	                    i += 1;
458	
459	                    lastEndTiming = endTiming;
460	                    if (endTiming >= finalTiming)
461	                    {
462	                        break;
463	                    }
464	                }
465	
466	                for (int j = segments.Count - 1; j >= i; j--)
467	                {
468	                    segments.RemoveAt(j);
469	                }
470	            }
471	            else if (segments.Count > 0)
472	            {
473	                // realign segment timing
474	                int firstTiming = segments[0].Timing;
475	                double firstFloorPos = segments[0].FloorPosition;
476	                for (int i = 0; i < segments.Count; i++)
477	                {
478	                    ArcSegmentData segment = segments[i];
479	                    segment.Timing = segment.Timing - firstTiming + Timing;
480	                    segment.EndTiming = segment.EndTiming - firstTiming + Timing;
481	                    segment.FloorPosition = segment.FloorPosition - firstFloorPos + FloorPosition;
482	                    segment.EndFloorPosition = segment.EndFloorPosition - firstFloorPos + FloorPosition;
483	                    segments[i] = segment;
484	                }
485	            }
486	        }
487	
488	        private (bool shouldDrawArcCap, Matrix4x4 arcCapMatrix, Vector4 arcCapColor) UpdateSegmentsAndArcCap(
489	            int currentTiming,
490	            double currentFloorPosition,
491	            int clipToTiming,
492	            double clipToFloorPosition,
493	            Vector3 fallDirection,
494	            float z,
495	            bool noclip)
496	        {
497	            for (int i = 0; i < segments.Count; i++)
498	            {
499	                ArcSegmentData segment = segments[i];
500	                if (clipToTiming >= segment.EndTiming && currentTiming >= segment.EndTiming && !noclip)
501	                {
502	                    segment.From = 1;
503	                }
504	                else if (clipToTiming <= segment.Timing || noclip)
505	                {
506	                    segment.From = 0;
507	                }
508	                else
509	                {
510	                    float p = (float)((clipToFloorPosition - segment.FloorPosition) / (segment.EndFloorPosition - segment.FloorPosition));
511	                    segment.From = p;
512	                }
513	
514	                segments[i] = segment;
515	
516	                if (currentTiming >= segment.Timing && currentTiming < segment.EndTiming)
517	                {
518	                    float p = (float)((currentFloorPosition - segment.FloorPosition) / (segment.EndFloorPosition - segment.FloorPosition));
519	                    if (segment.EndFloorPosition == segment.FloorPosition)
520	                    {
521	                        p = 0;
522	                    }
523	
524	                    Vector3 capPos = segment.StartPosition + (p * (segment.EndPosition - segment.StartPosition)) - (fallDirection * z);
525	                    Quaternion capRot = Quaternion.identity;
526	                    if (isControllerMode)
527	                    {
528	                        Vector3 displacement = segment.EndPosition - segment.StartPosition;
529	                        if (IsTrace || (Mathf.Approximately(displacement.x, 0) && Mathf.Approximately(displacement.y, 0)))
530	                        {
531	                            return (false, default, default);
532	                        }
533	
534	                        displacement.z = 0;
535	                        capRot = Quaternion.FromToRotation(Vector3.up, displacement);
536	                    }
537	
538	                    Vector3 capScale = new Vector3(ArcCapSize, ArcCapSize, 1);
539	
540	                    Vector4 color = new Vector4(1, 1, 1, IsTrace ? Values.TraceCapAlpha : Values.ArcCapAlpha);
541	                    return (true, Matrix4x4.TRS(capPos, capRot, capScale), color);
542	                }
543	            }
544	
545	            if (currentTiming <= Timing)
546	            {
547	                if (IsFirstArcOfGroup && !IsTrace && !isControllerMode)
548	                {
549	                    float approach = Mathf.Clamp(1 - (Mathf.Abs(z) / Values.TrackLengthForward), 0, 1);
550	                    float size = Values.ArcCapSize + (Values.ArcCapSizeAdditionMax * (1 - approach));
551	
552	                    Vector3 capPos = -(fallDirection * z);
553	                    Vector3 scale = new Vector3(size, size, 1);
554	                    Vector4 color = new Color(1, 1, 1, IsTrace ? 0 : approach);
555	
556	                    return (true, Matrix4x4.TRS(capPos, Quaternion.identity, scale), color);
557	                }
558	                else
559	                {
560	                    return (false, default, default);
561	                }
562	            }
563	
564	            return (false, default, default);
565	        }
566	
567	        private void SetGroupHighlight(bool highlight, int longParticleUntil)
568	        {
569	            if (recursivelyCalled)
570	            {
571	                return;
572	            }
573	
574	            recursivelyCalled = true;
575	            NextArc?.SetGroupHighlight(highlight, longParticleUntil);
576	
577	            this.highlight = highlight;
578	            this.longParticleUntil = longParticleUntil;
579	            recursivelyCalled = false;
580	        }
581	
582	        private void SetBranchFirst(Arc arc)
583	        {
584	            if (recursivelyCalled)
585	            {
586	                return;
587	            }
588	
589	            recursivelyCalled = true;
590	            NextArc?.SetBranchFirst(arc);
591	
592	            firstArcOfBranch = arc;
593	            recursivelyCalled = false;
594	        }
595	    }
596	}
