/// Build arc segments. Call once on chart load and when arc changes.
pub fn rebuild_segments(
    arc: &Arc,
    state: &mut ArcState,
    get_floor_position: &dyn Fn(i32) -> f64,
    arc_resolution: f32,
    next_arc: Option<&Arc>,
