        final_x = arc_formula::arc_x_to_world(arc.x2);
        final_y = arc_formula::arc_y_to_world(arc.y2);
    }

    state.segments.clear();
    let mut last_end_timing = arc.start;
    let mut last_end_fp = get_floor_position(arc.start);
