/// Compute body + shadow matrices for a normal arc segment.
/// Port of ArcSegmentData.GetMatrices.
fn get_segment_matrices(
    seg: &ArcSegmentData,
    current_fp: f64,
    fall_dir: Vec3,
    base_z: f32,
    base_y: f32,
    drop_rate: f32,
) -> (Mat4, Mat4) {
    let start_z = arc_formula::floor_position_to_z(seg.floor_position - current_fp, drop_rate);
    let end_z = arc_formula::floor_position_to_z(seg.end_floor_position - current_fp, drop_rate);

    let mut start_pos = seg.start_position + (start_z - base_z) * fall_dir;
    let end_pos = seg.end_position + (end_z - base_z) * fall_dir;
    start_pos = (end_pos - start_pos) * seg.from + start_pos;
    let dir = end_pos - start_pos;

    let body = Mat4::from_cols(
        Vec4::new(1.0, 0.0, 0.0, 0.0),
        Vec4::new(0.0, 1.0, 0.0, 0.0),
        Vec4::new(dir.x, dir.y, dir.z, 0.0),
        Vec4::new(start_pos.x, start_pos.y, start_pos.z, 1.0),
