/// Update rendering for a single arc note.
pub fn update_render(
    arc: &Arc,
    state: &mut ArcState,
    current_timing: Ms,
    current_fp: f64,
    floor_position: f64,
    drop_rate: f32,
    red_arc_value: f32,
    props: &GroupProperties,
    camera: &CameraService,
    render: &mut RenderService,
) {
    let z = arc_formula::floor_position_to_z(floor_position - current_fp, drop_rate);

    let base_x = arc_formula::arc_x_to_world(arc.x1);
    let base_y = arc_formula::arc_y_to_world(arc.y1);
    let base_pos = Vec3::new(base_x, base_y, 0.0);
    let pos = props.fall_direction * z + base_pos;
    let matrix = props.group_matrix
        * Mat4::from_scale_rotation_translation(props.scale_individual, props.rotation_individual, pos);

    // Alpha
    let mut alpha = 1.0_f32;
    if !arc.is_trace {
        if state.highlight {
            state.flash_count = (state.flash_count + 1) % ARC_FLASH_CYCLE;
            if state.flash_count == 0 {
                alpha = FLASH_ARC_ALPHA_SCALAR;
            }
        } else {
            let branch_timing = state.first_branch_timing.unwrap_or(arc.start);
            if current_timing >= branch_timing {
                alpha = MISSED_ARC_ALPHA_SCALAR;
            }
        }
        alpha *= MAX_ARC_ALPHA;
    }

    let mut color = props.color;
    color.w *= alpha.min(state.arc_group_alpha);

    // Clip timing
    let (clip_timing, clip_fp) = if state.has_been_hit_once || arc.is_trace || props.no_input || arc.start == arc.end {
        (current_timing, current_fp)
    } else {
        (arc.start, floor_position)
    };

    // Update segment From + find arc cap
    let mut cap_result: Option<(Mat4, Vec4)> = None;
    for seg in &mut state.segments {
        if clip_timing >= seg.end_timing && current_timing >= seg.end_timing && !props.no_clip {
            seg.from = 1.0;
        } else if clip_timing <= seg.timing || props.no_clip {
            seg.from = 0.0;
        } else {
            let denom = seg.end_floor_position - seg.floor_position;
            seg.from = if denom.abs() < 1e-10 { 0.0 } else {
                ((clip_fp - seg.floor_position) / denom) as f32
            };
        }

        if current_timing >= seg.timing && current_timing < seg.end_timing && cap_result.is_none() {
            let denom = seg.end_floor_position - seg.floor_position;
            let p = if denom.abs() < 1e-10 { 0.0 } else {
                ((current_fp - seg.floor_position) / denom) as f32
            };
            let cap_pos = seg.start_position + p * (seg.end_position - seg.start_position) - props.fall_direction * z;
            let cap_size = if arc.is_trace { TRACE_CAP_SIZE } else { ARC_CAP_SIZE };
            let cap_alpha = if arc.is_trace { TRACE_CAP_ALPHA } else { ARC_CAP_ALPHA };
            let cap_mat = Mat4::from_scale_rotation_translation(
                Vec3::new(cap_size, cap_size, 1.0),
                Quat::IDENTITY,
                cap_pos,
            );
            cap_result = Some((cap_mat, Vec4::new(1.0, 1.0, 1.0, cap_alpha)));
        }
    }

    // Approach cap (before arc starts)
    if cap_result.is_none() && current_timing <= arc.start && state.is_first_of_group && !arc.is_trace {
        let approach = (1.0 - z.abs() / TRACK_LENGTH_FORWARD).clamp(0.0, 1.0);
        let size = ARC_CAP_SIZE + ARC_CAP_SIZE_ADDITION_MAX * (1.0 - approach);
        let cap_pos = -(props.fall_direction * z);
        let cap_mat = Mat4::from_scale_rotation_translation(
            Vec3::new(size, size, 1.0),
            Quat::IDENTITY,
            cap_pos,
        );
        cap_result = Some((cap_mat, Vec4::new(1.0, 1.0, 1.0, approach)));
    }

    // Draw segments
    let selected = if state.is_selected { 1.0 } else { 0.0 };
    for seg in &state.segments {
        if seg.from > 1.0 {
            continue;
        }
        let z_pos = seg.calculate_z(current_fp, drop_rate);
        let end_z_pos = seg.calculate_end_z(current_fp, drop_rate);
        if (z_pos < -TRACK_LENGTH_FORWARD && end_z_pos < -TRACK_LENGTH_FORWARD)
            || (z_pos > TRACK_LENGTH_BACKWARD && end_z_pos > TRACK_LENGTH_BACKWARD)
        {
            continue;
        }
        if arc.start != arc.end && z_pos == end_z_pos {
            continue;
        }

        let midpoint = pos + (seg.start_position + seg.end_position) * 0.5;
        let mid_z = (z_pos + end_z_pos) * 0.5;
        let depth = camera.calculate_depth_squared(Vec3::new(midpoint.x, midpoint.y, mid_z));

        let (body_mat, shadow_mat) = get_segment_matrices(seg, current_fp, props.fall_direction, z, pos.y, drop_rate);

        if arc.is_trace {
            let trace_color: [f32; 4] = color.into();
            render.draw_trace_segment(
                InstanceData::new(matrix * body_mat, trace_color, [selected, 0.0, 0.0, 0.0]),
                depth,
            );
            if !props.no_shadow {
                render.draw_trace_shadow(InstanceData::new(matrix * shadow_mat, trace_color, [0.0; 4]));
            }
        } else {
            let arc_color: [f32; 4] = color.into();
            render.draw_arc_segment(
                InstanceData::new(matrix * body_mat, arc_color, [selected, 0.0, 0.0, 0.0]),
                depth,
            );
            if !props.no_shadow {
                render.draw_arc_shadow(InstanceData::new(matrix * shadow_mat, arc_color, [0.0; 4]));
            }
        }
    }

    // Height indicator
    let should_draw_height = !arc.is_trace && (arc.y1 != arc.y2 || state.is_first_of_group);
    if !props.no_height_indicator && (clip_timing <= arc.start || props.no_clip) && should_draw_height {
        let h = pos.y - TRACE_MESH_OFFSET / 2.0;
        let hi_matrix = Mat4::from_scale(Vec3::new(1.0, h, 1.0));
        let hi_color: [f32; 4] = (color * 0.8).into(); // slightly dimmed
        render.draw_height_indicator(InstanceData::new(matrix * hi_matrix, hi_color, [0.0; 4]));
    }

    // Arc head
    if !props.no_head && (clip_timing <= arc.start || props.no_clip) && state.is_first_of_group {
        let head_color: [f32; 4] = color.into();
        if arc.is_trace {
            render.draw_trace_head(InstanceData::new(matrix, head_color, [selected, 0.0, 0.0, 0.0]));
        } else {
            render.draw_arc_head(InstanceData::new(matrix, head_color, [selected, 0.0, 0.0, 0.0]));
        }
    }

    // Arc cap
    if !props.no_arc_cap {
        if let Some((cap_mat, cap_color)) = cap_result {
            let cc: [f32; 4] = (cap_color * props.color).into();
            render.draw_arc_cap(InstanceData::new(matrix * cap_mat, cc, [0.0; 4]));
        }
    }
}

/// Compute the world X position of this arc at a given timing.
pub fn world_x_at(arc: &Arc, timing: Ms) -> f32 {
    if arc.end == arc.start {
        return arc_formula::arc_x_to_world(if timing <= arc.start { arc.x1 } else { arc.x2 });
    }
    let p = ((timing - arc.start) as f32 / (arc.end - arc.start) as f32).clamp(0.0, 1.0);
    arc_formula::arc_x_to_world(arc_formula::arc_x(arc.x1, arc.x2, p, arc.easing))
}

/// Compute the world Y position of this arc at a given timing.
pub fn world_y_at(arc: &Arc, timing: Ms) -> f32 {
    if arc.end == arc.start {
        return arc_formula::arc_y_to_world(if timing <= arc.start { arc.y1 } else { arc.y2 });
    }
    let p = ((timing - arc.start) as f32 / (arc.end - arc.start) as f32).clamp(0.0, 1.0);
    arc_formula::arc_y_to_world(arc_formula::arc_y(arc.y1, arc.y2, p, arc.easing))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn make_arc() -> Arc {
        Arc {
            start: 0,
            end: 1000,
            x1: 0.0,
            x2: 1.0,
            easing: Easing::S,
            y1: 0.0,
            y2: 1.0,
            color: 0,
            sfx: String::new(),
            is_trace: false,
            sky_notes: Vec::new(),
        }
    }

    #[test]
    fn test_world_x_at_endpoints() {
        let arc = make_arc();
        let x0 = world_x_at(&arc, 0);
        let x1 = world_x_at(&arc, 1000);
        assert!((x0 - arc_formula::arc_x_to_world(0.0)).abs() < 1e-3);
        assert!((x1 - arc_formula::arc_x_to_world(1.0)).abs() < 1e-3);
    }

    #[test]
    fn test_world_y_at_midpoint() {
        let arc = make_arc();
        let y = world_y_at(&arc, 500);
        let expected = arc_formula::arc_y_to_world(0.5);
        assert!((y - expected).abs() < 1e-3);
    }

    #[test]
    fn test_rebuild_segments_count() {
        let arc = make_arc();
        let mut state = ArcState::default();
        let get_fp = |t: i32| t as f64 * 100.0;
        rebuild_segments(&arc, &mut state, &get_fp, 1.0, None);
        assert!(!state.segments.is_empty());
        assert!(state.segments.len() >= 10); // 1000ms / ~71ms per segment
    }

    #[test]
    fn test_segment_matrices_basic() {
        let seg = ArcSegmentData {
            timing: 0,
            end_timing: 71,
            start_position: Vec3::ZERO,
            end_position: Vec3::new(1.0, 0.5, 0.0),
            floor_position: 0.0,
            end_floor_position: 7100.0,
            from: 0.0,
        };
        crate::values::set_base_bpm(100.0);
        let (body, shadow) = get_segment_matrices(&seg, 0.0, Vec3::new(0.0, 0.0, -1.0), 0.0, 1.0, 30.0);
        // body column 3 (translation) should be at start_position
        assert!((body.w_axis.x).abs() < 1e-3);
        // shadow should have y = -base_y
        assert!((shadow.w_axis.y - (-1.0)).abs() < 1e-3);
    }
}

