// ArcCreate ArcTap.cs UpdateRender port
// Reference: re/ArcCreate/Assets/Scripts/Gameplay/Data/Events/ArcTap.cs

use glam::{Mat4, Vec3};
use crate::chart::types::{SkyNote, GroupProperties, Ms};
use crate::gameplay::arc_formula;
use crate::render::render_service::RenderService;
use crate::render::vertex::InstanceData;

/// Runtime state for an arctap (sky note).
pub struct ArcTapState {
    pub is_hit: bool,
    pub is_selected: bool,
    pub sfx_played: bool,
}

impl Default for ArcTapState {
    fn default() -> Self {
        Self { is_hit: false, is_selected: false, sfx_played: false }
    }
}

/// Update rendering for a single arctap.
pub fn update_render(
    _sky_note: &SkyNote,
    state: &ArcTapState,
    world_x: f32,
    world_y: f32,
    width: f32,
    floor_position: f64,
    current_fp: f64,
    drop_rate: f32,
    is_sfx: bool,
    props: &GroupProperties,
    render: &mut RenderService,
) -> bool {
    if state.is_hit && !props.no_clip {
        return false;
    }

    let z = arc_formula::floor_position_to_z(floor_position - current_fp, drop_rate);
    if !arc_formula::within_render_range(z) {
        return false;
    }

    let pos = props.fall_direction * z + Vec3::new(world_x, world_y, 0.0);
    let rot = props.rotation_individual;
    let mut scl = props.scale_individual;
    scl.x *= width;

    let matrix = props.group_matrix * Mat4::from_scale_rotation_translation(scl, rot, pos);

    let alpha = arc_formula::calculate_fade_out_alpha(z);
    let mut color = props.color;
    color.w *= alpha;

    let selected = if state.is_selected { 1.0 } else { 0.0 };
    render.draw_arctap(
        InstanceData::new(matrix, color.into(), [selected, 0.0, 0.0, 0.0]),
        is_sfx,
    );

    // Shadow
    if !props.no_shadow {
        let shadow_matrix = matrix * Mat4::from_translation(Vec3::new(0.0, -pos.y, 0.0));
        render.draw_arctap_shadow(InstanceData::new(shadow_matrix, color.into(), [0.0; 4]));
    }

    true
}

