// ArcCreate TimingGroup.Timing.cs port
// Reference: re/ArcCreate/Assets/Scripts/Gameplay/Chart/TimingGroup.Timing.cs

use crate::chart::types::{Timing, GroupProperties, GroupAttrs};

/// Runtime timing group with floor position cache.
pub struct RuntimeTimingGroup {
    pub id: usize,
    pub timings: Vec<CachedTiming>,
    pub properties: GroupProperties,
}

/// Timing event with cached floor position.
#[derive(Clone, Debug)]
pub struct CachedTiming {
    pub time: i32,
    pub bpm: f32,
    pub divisor: f32,
    pub floor_position: f64,
}

impl RuntimeTimingGroup {
    pub fn new(id: usize, timings: &[Timing], attrs: &GroupAttrs) -> Self {
        let mut cached: Vec<CachedTiming> = timings
            .iter()
            .map(|t| CachedTiming {
                time: t.time,
                bpm: t.bpm,
                divisor: t.divisor,
                floor_position: 0.0,
            })
            .collect();

        recalculate_floor_positions(&mut cached);

        Self {
            id,
            timings: cached,
            properties: GroupProperties::from_attrs(attrs),
        }
    }

    pub fn get_floor_position(&self, timing: i32) -> f64 {
        let event = self.get_event_at(timing);
        event.floor_position + event.bpm as f64 * (timing - event.time) as f64
    }

    pub fn get_bpm(&self, timing: i32) -> f32 {
        self.get_event_at(timing).bpm
    }

    /// Binary search for the timing event active at the given time.
    fn get_event_at(&self, timing: i32) -> &CachedTiming {
        let idx = self.timings.partition_point(|e| e.time <= timing);
        &self.timings[if idx > 0 { idx - 1 } else { 0 }]
    }

    /// Reverse lookup: floor position → timing.
    /// Returns the timing closest to `hint_timing`.
    pub fn get_timing_from_floor_position(&self, fp: f64) -> i32 {
        for i in 0..self.timings.len() {
            let curr = &self.timings[i];
            let next_fp = if i + 1 < self.timings.len() {
                self.timings[i + 1].floor_position
            } else {
                f64::MAX
            };

            if fp >= curr.floor_position && fp < next_fp {
                if curr.bpm.abs() < 1e-10 {
                    return curr.time;
                }
                return curr.time + ((fp - curr.floor_position) / curr.bpm as f64) as i32;
            }
        }

        if let Some(last) = self.timings.last() {
            last.time + ((fp - last.floor_position) / last.bpm as f64) as i32
        } else {
            0
        }
    }

    pub fn get_floor_position_fn(&self) -> impl Fn(i32) -> f64 + '_ {
        move |timing| self.get_floor_position(timing)
    }
}

fn recalculate_floor_positions(timings: &mut [CachedTiming]) {
    if timings.is_empty() {
        return;
    }
    timings[0].floor_position = 0.0;
    for i in 1..timings.len() {
        let dt = (timings[i].time - timings[i - 1].time) as f64;
        timings[i].floor_position = timings[i - 1].floor_position + timings[i - 1].bpm as f64 * dt;
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::chart::types::GroupAttrs;

    fn make_timings(bpms: &[(i32, f32)]) -> Vec<Timing> {
        bpms.iter()
            .map(|&(time, bpm)| Timing { time, bpm, divisor: 4.0 })
            .collect()
    }

    #[test]
    fn test_single_bpm() {
        let tg = RuntimeTimingGroup::new(0, &make_timings(&[(0, 120.0)]), &GroupAttrs::default());
        let fp = tg.get_floor_position(1000);
        assert!((fp - 120_000.0).abs() < 1.0, "fp={fp}");
    }

    #[test]
    fn test_bpm_change() {
        let tg = RuntimeTimingGroup::new(
            0,
            &make_timings(&[(0, 120.0), (1000, 240.0)]),
            &GroupAttrs::default(),
        );
        // At t=1500: fp(1000)=120*1000=120000, then 240*500=120000 → total 240000
        let fp = tg.get_floor_position(1500);
        assert!((fp - 240_000.0).abs() < 1.0, "fp={fp}");
    }

    #[test]
    fn test_floor_position_at_timing_boundaries() {
        let tg = RuntimeTimingGroup::new(
            0,
            &make_timings(&[(0, 100.0), (500, 200.0)]),
            &GroupAttrs::default(),
        );
        let fp0 = tg.get_floor_position(0);
        assert!((fp0 - 0.0).abs() < 1.0);

        let fp500 = tg.get_floor_position(500);
        assert!((fp500 - 50_000.0).abs() < 1.0, "fp500={fp500}");
    }

    #[test]
    fn test_reverse_lookup() {
        let tg = RuntimeTimingGroup::new(0, &make_timings(&[(0, 120.0)]), &GroupAttrs::default());
        let fp = tg.get_floor_position(1000);
        let t = tg.get_timing_from_floor_position(fp);
        assert!((t - 1000).abs() <= 1, "t={t}");
    }

    #[test]
    fn test_get_bpm() {
        let tg = RuntimeTimingGroup::new(
            0,
            &make_timings(&[(0, 120.0), (1000, 240.0)]),
            &GroupAttrs::default(),
        );
        assert_eq!(tg.get_bpm(500), 120.0);
        assert_eq!(tg.get_bpm(1500), 240.0);
    }

    #[test]
    fn test_negative_timing() {
        let tg = RuntimeTimingGroup::new(0, &make_timings(&[(0, 120.0)]), &GroupAttrs::default());
        let fp = tg.get_floor_position(-100);
        assert!((fp - (-12_000.0)).abs() < 1.0, "fp={fp}");
    }
}

