use crate::values::*;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum JudgmentResult {
    Max,
    PerfectEarly,
    PerfectLate,
    GoodEarly,
    GoodLate,
    MissEarly,
    MissLate,
}

impl JudgmentResult {
    pub fn from_offset(offset: i32) -> Self {
        let abs = offset.abs();
        if abs <= MAX_JUDGE_WINDOW {
            Self::Max
        } else if abs <= PERFECT_JUDGE_WINDOW {
            if offset < 0 { Self::PerfectEarly } else { Self::PerfectLate }
        } else if abs <= GOOD_JUDGE_WINDOW {
            if offset < 0 { Self::GoodEarly } else { Self::GoodLate }
        } else {
            if offset < 0 { Self::MissEarly } else { Self::MissLate }
        }
    }

    pub fn is_miss(&self) -> bool {
        matches!(self, Self::MissEarly | Self::MissLate)
    }

    pub fn is_max(&self) -> bool {
        matches!(self, Self::Max)
    }

    pub fn is_good(&self) -> bool {
        matches!(self, Self::GoodEarly | Self::GoodLate)
    }

    pub fn is_perfect(&self) -> bool {
        matches!(self, Self::PerfectEarly | Self::PerfectLate)
    }
}

/// Request for judging a lane tap note.
pub struct LaneTapRequest {
    pub start_at_timing: i32,
    pub expire_at_timing: i32,
    pub auto_at_timing: i32,
    pub lane: i32,
    pub group_index: usize,
    pub note_index: usize,
}

/// Request for judging a lane hold note (continuous).
pub struct LaneHoldRequest {
    pub start_at_timing: i32,
    pub expire_at_timing: i32,
    pub auto_at_timing: i32,
    pub lane: i32,
    pub group_index: usize,
    pub note_index: usize,
    pub is_judgment: bool,
}

/// Request for judging an arc note (continuous tracking).
pub struct ArcRequest {
    pub start_at_timing: i32,
    pub expire_at_timing: i32,
    pub auto_at_timing: i32,
    pub group_index: usize,
    pub arc_index: usize,
    pub is_judgment: bool,
}

/// Request for judging an arctap (sky note).
pub struct ArcTapRequest {
    pub start_at_timing: i32,
    pub expire_at_timing: i32,
    pub auto_at_timing: i32,
    pub group_index: usize,
    pub arc_index: usize,
    pub sky_note_index: usize,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_judgment_windows() {
        assert!(JudgmentResult::from_offset(0).is_max());
        assert!(JudgmentResult::from_offset(25).is_max());
        assert!(JudgmentResult::from_offset(-25).is_max());
        assert!(JudgmentResult::from_offset(26).is_perfect());
        assert!(JudgmentResult::from_offset(50).is_perfect());
        assert!(JudgmentResult::from_offset(-50).is_perfect());
        assert!(JudgmentResult::from_offset(51).is_good());
        assert!(JudgmentResult::from_offset(100).is_good());
        assert!(JudgmentResult::from_offset(-100).is_good());
        assert!(JudgmentResult::from_offset(101).is_miss());
        assert!(JudgmentResult::from_offset(-101).is_miss());
    }

    #[test]
    fn test_early_late() {
        assert_eq!(JudgmentResult::from_offset(-30), JudgmentResult::PerfectEarly);
        assert_eq!(JudgmentResult::from_offset(30), JudgmentResult::PerfectLate);
        assert_eq!(JudgmentResult::from_offset(-60), JudgmentResult::GoodEarly);
        assert_eq!(JudgmentResult::from_offset(60), JudgmentResult::GoodLate);
        assert_eq!(JudgmentResult::from_offset(-200), JudgmentResult::MissEarly);
        assert_eq!(JudgmentResult::from_offset(200), JudgmentResult::MissLate);
    }
}

