// ArcCreate JudgementService port
// Reference: re/ArcCreate/Assets/Scripts/Gameplay/Judgement/JudgementService.cs

use crate::judgment::requests::*;

/// Callback for processing judgment results.
pub trait JudgmentCallback {
    fn on_lane_tap_judged(&mut self, group: usize, note: usize, offset: i32);
    fn on_lane_tap_missed(&mut self, group: usize, note: usize);
    fn on_lane_hold_judged(&mut self, group: usize, note: usize, is_expired: bool, is_judgment: bool);
    fn on_arc_judged(&mut self, group: usize, arc: usize, is_expired: bool, is_judgment: bool);
    fn on_arc_tap_judged(&mut self, group: usize, arc: usize, sky: usize, offset: i32);
    fn on_arc_tap_missed(&mut self, group: usize, arc: usize, sky: usize);
}

/// Request-based judgment service.
/// Notes submit requests when they approach; the service processes input against them.
pub struct JudgmentService {
    pub lane_tap_requests: Vec<LaneTapRequest>,
    pub lane_hold_requests: Vec<LaneHoldRequest>,
    pub arc_requests: Vec<ArcRequest>,
    pub arc_tap_requests: Vec<ArcTapRequest>,
}

impl JudgmentService {
    pub fn new() -> Self {
        Self {
            lane_tap_requests: Vec::with_capacity(32),
            lane_hold_requests: Vec::with_capacity(32),
            arc_requests: Vec::with_capacity(32),
            arc_tap_requests: Vec::with_capacity(32),
        }
    }

    pub fn clear(&mut self) {
        self.lane_tap_requests.clear();
        self.lane_hold_requests.clear();
        self.arc_requests.clear();
        self.arc_tap_requests.clear();
    }

    /// Prune expired requests, triggering auto-miss callbacks.
    pub fn prune_expired(&mut self, current_timing: i32, cb: &mut dyn JudgmentCallback) {
        self.lane_tap_requests.retain(|req| {
            if current_timing >= req.expire_at_timing {
                cb.on_lane_tap_missed(req.group_index, req.note_index);
                false
            } else {
                true
            }
        });

        self.arc_tap_requests.retain(|req| {
            if current_timing >= req.expire_at_timing {
                cb.on_arc_tap_missed(req.group_index, req.arc_index, req.sky_note_index);
                false
            } else {
                true
            }
        });

        self.lane_hold_requests.retain(|req| {
            if current_timing >= req.expire_at_timing {
                cb.on_lane_hold_judged(req.group_index, req.note_index, true, req.is_judgment);
                false
            } else {
                true
            }
        });

        self.arc_requests.retain(|req| {
            if current_timing >= req.expire_at_timing {
                cb.on_arc_judged(req.group_index, req.arc_index, true, req.is_judgment);
                false
            } else {
                true
            }
        });
    }

    /// Process lane tap input: find the closest matching request for a given lane.
    /// Returns the offset if a match was found.
    pub fn match_lane_tap(
        &mut self,
        current_timing: i32,
        lane: i32,
        cb: &mut dyn JudgmentCallback,
    ) -> Option<i32> {
        let mut best_idx = None;
        let mut best_abs_offset = i32::MAX;

        for (i, req) in self.lane_tap_requests.iter().enumerate() {
            if req.lane != lane {
                continue;
            }
            if current_timing < req.start_at_timing {
                continue;
            }
            let offset = current_timing - req.auto_at_timing;
            if offset.abs() < best_abs_offset {
                best_abs_offset = offset.abs();
                best_idx = Some(i);
            }
        }

        if let Some(idx) = best_idx {
            let req = self.lane_tap_requests.remove(idx);
            let offset = current_timing - req.auto_at_timing;
            cb.on_lane_tap_judged(req.group_index, req.note_index, offset);
            Some(offset)
        } else {
            None
        }
    }

    /// Process arctap input: find closest matching arctap request (any position).
    pub fn match_arc_tap(
        &mut self,
        current_timing: i32,
        cb: &mut dyn JudgmentCallback,
    ) -> Option<i32> {
        let mut best_idx = None;
        let mut best_abs_offset = i32::MAX;

        for (i, req) in self.arc_tap_requests.iter().enumerate() {
            if current_timing < req.start_at_timing {
                continue;
            }
            let offset = current_timing - req.auto_at_timing;
            if offset.abs() < best_abs_offset {
                best_abs_offset = offset.abs();
                best_idx = Some(i);
            }
        }

        if let Some(idx) = best_idx {
            let req = self.arc_tap_requests.remove(idx);
            let offset = current_timing - req.auto_at_timing;
            cb.on_arc_tap_judged(req.group_index, req.arc_index, req.sky_note_index, offset);
            Some(offset)
        } else {
            None
        }
    }

    /// Check if a lane is being held (for hold note judgment).
    pub fn check_lane_hold(
        &mut self,
        current_timing: i32,
        held_lanes: &[bool; 4],
        cb: &mut dyn JudgmentCallback,
    ) {
        self.lane_hold_requests.retain(|req| {
            if current_timing < req.start_at_timing {
                return true;
            }
            let lane_idx = (req.lane - 1) as usize;
            if lane_idx >= 4 {
                return true;
            }
            let is_held = held_lanes[lane_idx];
            cb.on_lane_hold_judged(req.group_index, req.note_index, !is_held, req.is_judgment);
            false
        });
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    struct MockCallback {
        tap_results: Vec<(usize, usize, i32)>,
        tap_misses: Vec<(usize, usize)>,
    }

    impl MockCallback {
        fn new() -> Self {
            Self { tap_results: Vec::new(), tap_misses: Vec::new() }
        }
    }

    impl JudgmentCallback for MockCallback {
        fn on_lane_tap_judged(&mut self, g: usize, n: usize, offset: i32) {
            self.tap_results.push((g, n, offset));
        }
        fn on_lane_tap_missed(&mut self, g: usize, n: usize) {
            self.tap_misses.push((g, n));
        }
        fn on_lane_hold_judged(&mut self, _: usize, _: usize, _: bool, _: bool) {}
        fn on_arc_judged(&mut self, _: usize, _: usize, _: bool, _: bool) {}
        fn on_arc_tap_judged(&mut self, _: usize, _: usize, _: usize, _: i32) {}
        fn on_arc_tap_missed(&mut self, _: usize, _: usize, _: usize) {}
    }

    #[test]
    fn test_match_lane_tap() {
        let mut svc = JudgmentService::new();
        svc.lane_tap_requests.push(LaneTapRequest {
            start_at_timing: 900,
            expire_at_timing: 1120,
            auto_at_timing: 1000,
            lane: 2,
            group_index: 0,
            note_index: 0,
        });

        let mut cb = MockCallback::new();
        let result = svc.match_lane_tap(1010, 2, &mut cb);
        assert_eq!(result, Some(10));
        assert_eq!(cb.tap_results.len(), 1);
        assert_eq!(cb.tap_results[0].2, 10); // 10ms late
        assert!(svc.lane_tap_requests.is_empty());
    }

    #[test]
    fn test_wrong_lane_no_match() {
        let mut svc = JudgmentService::new();
        svc.lane_tap_requests.push(LaneTapRequest {
            start_at_timing: 900,
            expire_at_timing: 1120,
            auto_at_timing: 1000,
            lane: 2,
            group_index: 0,
            note_index: 0,
        });

        let mut cb = MockCallback::new();
        let result = svc.match_lane_tap(1010, 3, &mut cb);
        assert_eq!(result, None);
        assert_eq!(svc.lane_tap_requests.len(), 1);
    }

    #[test]
    fn test_prune_expired() {
        let mut svc = JudgmentService::new();
        svc.lane_tap_requests.push(LaneTapRequest {
            start_at_timing: 900,
            expire_at_timing: 1120,
            auto_at_timing: 1000,
            lane: 1,
            group_index: 0,
            note_index: 0,
        });

        let mut cb = MockCallback::new();
        svc.prune_expired(1200, &mut cb);
        assert!(svc.lane_tap_requests.is_empty());
        assert_eq!(cb.tap_misses.len(), 1);
    }
}

