// ArcCreate ScoreService port
// Reference: re/ArcCreate/Assets/Scripts/Gameplay/Score/ScoreService.cs

use crate::judgment::requests::JudgmentResult;
use crate::values::*;

struct ScoreEvent {
    timing: i32,
    score: f64,
}

pub struct ScoreService {
    pub note_count: i32,
    score_per_note: f64,
    current_score_full: f64,
    current_score_partial: f64,
    pending_events: Vec<ScoreEvent>,

    pub combo: i32,
    pub max_combo: i32,
    pub combo_redmix: f32,

    pub max_count: i32,
    pub perfect_early_count: i32,
    pub perfect_late_count: i32,
    pub good_early_count: i32,
    pub good_late_count: i32,
    pub miss_count: i32,
}

impl ScoreService {
    pub fn new(note_count: i32) -> Self {
        Self {
            note_count,
            score_per_note: if note_count > 0 { MAX_SCORE as f64 / note_count as f64 } else { 0.0 },
            current_score_full: 0.0,
            current_score_partial: 0.0,
            pending_events: Vec::new(),
            combo: 0,
            max_combo: 0,
            combo_redmix: 0.0,
            max_count: 0,
            perfect_early_count: 0,
            perfect_late_count: 0,
            good_early_count: 0,
            good_late_count: 0,
            miss_count: 0,
        }
    }

    pub fn process_judgment(&mut self, result: JudgmentResult, timing: i32) {
        let score = if result.is_max() {
            self.score_per_note + 1.0
        } else if result.is_good() {
            self.score_per_note * GOOD_PENALTY_MULTIPLIER
        } else if result.is_miss() {
            0.0
        } else {
            self.score_per_note
        };

        self.pending_events.push(ScoreEvent { timing, score });

        if result.is_miss() {
            self.combo = 0;
            self.combo_redmix = 1.0;
        } else {
            self.combo += 1;
            self.max_combo = self.max_combo.max(self.combo);
        }

        match result {
            JudgmentResult::Max => self.max_count += 1,
            JudgmentResult::PerfectEarly => self.perfect_early_count += 1,
            JudgmentResult::PerfectLate => self.perfect_late_count += 1,
            JudgmentResult::GoodEarly => self.good_early_count += 1,
            JudgmentResult::GoodLate => self.good_late_count += 1,
            JudgmentResult::MissEarly | JudgmentResult::MissLate => self.miss_count += 1,
        }
    }

    pub fn update(&mut self, current_timing: i32, delta_time: f32) {
        self.current_score_partial = 0.0;
        self.pending_events.retain(|e| {
            let elapsed = current_timing - e.timing;
            if elapsed >= SCORE_MODIFY_DELAY {
                self.current_score_full += e.score;
                false
            } else {
                let partial = elapsed as f64 / SCORE_MODIFY_DELAY as f64;
                self.current_score_partial += partial * e.score;
                true
            }
        });
        self.combo_redmix = (self.combo_redmix - delta_time / COMBO_LOST_FLASH_DURATION).max(0.0);
    }

    pub fn current_score(&self) -> i32 {
        (self.current_score_full + self.current_score_partial) as i32
    }

    pub fn pure_count(&self) -> i32 {
        self.max_count + self.perfect_early_count + self.perfect_late_count
    }

    pub fn far_count(&self) -> i32 {
        self.good_early_count + self.good_late_count
    }

    pub fn total_judged(&self) -> i32 {
        self.pure_count() + self.far_count() + self.miss_count
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_perfect_score_all_max() {
        let mut svc = ScoreService::new(100);
        for _ in 0..100 {
            svc.process_judgment(JudgmentResult::Max, 0);
        }
        svc.update(10000, 0.0);
        let score = svc.current_score();
        // Each max = 100000 + 1 = 100001, total = 10000100
        assert_eq!(score, 10_000_100);
    }

    #[test]
    fn test_combo_breaks_on_miss() {
        let mut svc = ScoreService::new(10);
        svc.process_judgment(JudgmentResult::Max, 0);
        svc.process_judgment(JudgmentResult::Max, 100);
        assert_eq!(svc.combo, 2);
        svc.process_judgment(JudgmentResult::MissLate, 200);
        assert_eq!(svc.combo, 0);
        assert_eq!(svc.max_combo, 2);
    }

    #[test]
    fn test_score_delayed_animation() {
        let mut svc = ScoreService::new(1);
        svc.process_judgment(JudgmentResult::Max, 0);

        svc.update(250, 0.0);
        let partial = svc.current_score();
        assert!(partial > 0 && partial < 10_000_001, "partial={partial}");

        svc.update(600, 0.0);
        let full = svc.current_score();
        assert_eq!(full, 10_000_001);
    }

    #[test]
    fn test_good_penalty() {
        let mut svc = ScoreService::new(2);
        svc.process_judgment(JudgmentResult::Max, 0);
        svc.process_judgment(JudgmentResult::GoodEarly, 0);
        svc.update(10000, 0.0);
        let score = svc.current_score();
        // max = 5000000+1 = 5000001, good = 5000000*0.5 = 2500000
        assert_eq!(score, 7_500_001);
    }

    #[test]
    fn test_judgment_counts() {
        let mut svc = ScoreService::new(5);
        svc.process_judgment(JudgmentResult::Max, 0);
        svc.process_judgment(JudgmentResult::PerfectEarly, 0);
        svc.process_judgment(JudgmentResult::GoodLate, 0);
        svc.process_judgment(JudgmentResult::MissEarly, 0);
        svc.process_judgment(JudgmentResult::MissLate, 0);
        assert_eq!(svc.pure_count(), 2);
        assert_eq!(svc.far_count(), 1);
        assert_eq!(svc.miss_count, 2);
        assert_eq!(svc.total_judged(), 5);
    }
}

