109	fn create_mesh_buffer(device: &wgpu::Device, verts: &[Vertex], idxs: &[u32], label: &str) -> MeshBuffer {
110	    let vertex = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
111	        label: Some(&format!("{label}_verts")),
112	        contents: bytemuck::cast_slice(verts),
113	        usage: wgpu::BufferUsages::VERTEX,
114	    });
115	    let index = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
116	        label: Some(&format!("{label}_idxs")),
117	        contents: bytemuck::cast_slice(idxs),
118	        usage: wgpu::BufferUsages::INDEX,
119	    });
120	    MeshBuffer {
121	        vertex,
122	        index,
123	        index_count: idxs.len() as u32,
124	    }
125	}
126	
127	fn create_dynamic_buffer(device: &wgpu::Device, label: &str) -> MeshBuffer {
128	    let vertex = device.create_buffer(&wgpu::BufferDescriptor {
129	        label: Some(&format!("{label}_verts")),
130	        size: (500 * 4 * std::mem::size_of::<Vertex>()) as u64,
131	        usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
132	        mapped_at_creation: false,
133	    });
134	    let index = device.create_buffer(&wgpu::BufferDescriptor {
135	        label: Some(&format!("{label}_idxs")),
136	        size: (500 * 6 * std::mem::size_of::<u32>()) as u64,
137	        usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
138	        mapped_at_creation: false,
139	    });
140	    MeshBuffer {
141	        vertex,
142	        index,
143	        index_count: 0,
144	    }
145	}
