148	    pub async fn new(window: Arc<Window>, assets: &crate::assets::AssetLoader) -> Self {
149	        let size = window.inner_size();
150	
151	        let instance = wgpu::Instance::new(wgpu::InstanceDescriptor {
152	            backends: wgpu::Backends::all(),
153	            ..Default::default()
154	        });
155	
156	        let surface = instance
157	            .create_surface(window)
158	            .expect("failed to create surface");
159	
160	        let adapter = instance
161	            .request_adapter(&wgpu::RequestAdapterOptions {
162	                power_preference: wgpu::PowerPreference::HighPerformance,
163	                compatible_surface: Some(&surface),
164	                force_fallback_adapter: false,
165	            })
166	            .await
167	            .expect("no suitable GPU adapter");
168	
169	        log::info!("GPU: {:?}", adapter.get_info());
170	
171	        let limits = if cfg!(target_os = "android") {
172	            wgpu::Limits::downlevel_defaults()
173	        } else {
174	            wgpu::Limits::default()
175	        }
176	        .using_resolution(adapter.limits());
177	
178	        let (device, queue) = adapter
179	            .request_device(
180	                &wgpu::DeviceDescriptor {
181	                    label: Some("better-arc"),
182	                    required_features: wgpu::Features::empty(),
183	                    required_limits: limits,
184	                    ..Default::default()
185	                },
186	                None,
187	            )
188	            .await
189	            .expect("failed to create device");
190	
191	        // Surface
192	        let caps = surface.get_capabilities(&adapter);
193	        let format = caps
194	            .formats
195	            .iter()
196	            .find(|f| f.is_srgb())
197	            .copied()
198	            .unwrap_or(caps.formats[0]);
199	
200	        log::info!("surface present modes: {:?}", caps.present_modes);
201	
202	        let present_mode = if caps.present_modes.contains(&wgpu::PresentMode::Fifo) {
203	            wgpu::PresentMode::Fifo
204	        } else {
205	            wgpu::PresentMode::AutoVsync
206	        };
207	        log::info!("using present mode: {:?}", present_mode);
208	
209	        let config = wgpu::SurfaceConfiguration {
210	            usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
211	            format,
212	            width: size.width.max(1),
213	            height: size.height.max(1),
214	            present_mode,
215	            alpha_mode: caps.alpha_modes[0],
216	            view_formats: vec![],
217	            desired_maximum_frame_latency: 2,
218	        };
219	        surface.configure(&device, &config);
220	
221	        // Shader
222	        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
223	            label: Some("shader"),
224	            source: wgpu::ShaderSource::Wgsl(SHADER.into()),
225	        });
226	
227	        // Camera
228	        let camera = CameraService::new(config.width as f32, config.height as f32);
229	        let camera_uniform = CameraUniform::from_camera(&camera);
230	
231	        let camera_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
232	            label: Some("camera_uniform"),
233	            contents: bytemuck::cast_slice(&[camera_uniform]),
234	            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
235	        });
236	
237	        let camera_bgl = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
238	            label: Some("camera_bgl"),
239	            entries: &[wgpu::BindGroupLayoutEntry {
240	                binding: 0,
241	                visibility: wgpu::ShaderStages::VERTEX,
242	                ty: wgpu::BindingType::Buffer {
243	                    ty: wgpu::BufferBindingType::Uniform,
244	                    has_dynamic_offset: false,
245	                    min_binding_size: None,
246	                },
247	                count: None,
248	            }],
249	        });
250	
251	        let camera_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
252	            label: Some("camera_bg"),
253	            layout: &camera_bgl,
254	            entries: &[wgpu::BindGroupEntry {
255	                binding: 0,
256	                resource: camera_buffer.as_entire_binding(),
257	            }],
258	        });
259	
260	        // Textures
261	        let tex_bgl = texture::texture_bind_group_layout(&device);
262	        let tex_white = texture::white_texture(&device, &queue, &tex_bgl);
263	
264	        let load = |name: &str, label: &str| -> wgpu::BindGroup {
265	            match assets.load_bytes(&format!("extracted/{name}")) {
266	                Ok(bytes) => texture::load_texture_from_bytes(&device, &queue, &tex_bgl, &bytes, label),
267	                Err(e) => {
268	                    log::warn!("{name}: {e}, using white fallback");
269	                    texture::white_texture(&device, &queue, &tex_bgl)
270	                }
271	            }
272	        };
273	
274	        let tex_track = load("track.png", "track");
275	        let tex_divider = load("track_lane_divider.png", "divider");
276	        let tex_judgment = load("track_critical_line.png", "judgment");
277	        let tex_note = load("note.png", "note");
278	        let tex_hold = load("note_hold.png", "note_hold");
279	        let tex_arc_body = load("arc_body.png", "arc_body");
280	        let tex_arc_body_hi = load("arc_body_hi.png", "arc_body_hi");
281	        let tex_arc_cap = load("arc_cap.png", "arc_cap");
282	        let tex_sky = load("sfx_l_note.jpg", "sky_note");
283	        let tex_lane_hit = load("lane_hit.png", "lane_hit");
284	        let tex_hit_pure = load("hit_pure.png", "hit_pure");
285	        let tex_hit_far = load("hit_far.png", "hit_far");
286	
287	        // Pipeline (now with texture bind group)
288	        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
289	            label: Some("pipeline_layout"),
290	            bind_group_layouts: &[&camera_bgl, &tex_bgl],
291	            push_constant_ranges: &[],
292	        });
293	
294	        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
295	            label: Some("main"),
296	            layout: Some(&pipeline_layout),
297	            vertex: wgpu::VertexState {
298	                module: &shader,
299	                entry_point: Some("vs_main"),
300	                buffers: &[Vertex::layout()],
301	                compilation_options: Default::default(),
302	            },
303	            fragment: Some(wgpu::FragmentState {
304	                module: &shader,
305	                entry_point: Some("fs_main"),
306	                targets: &[Some(wgpu::ColorTargetState {
307	                    format,
308	                    blend: Some(wgpu::BlendState::ALPHA_BLENDING),
309	                    write_mask: wgpu::ColorWrites::ALL,
310	                })],
311	                compilation_options: Default::default(),
312	            }),
313	            primitive: wgpu::PrimitiveState {
314	                topology: wgpu::PrimitiveTopology::TriangleList,
315	                cull_mode: None,
316	                ..Default::default()
317	            },
318	            depth_stencil: Some(wgpu::DepthStencilState {
319	                format: wgpu::TextureFormat::Depth32Float,
320	                depth_write_enabled: true,
321	                depth_compare: wgpu::CompareFunction::Less,
322	                stencil: wgpu::StencilState::default(),
323	                bias: wgpu::DepthBiasState::default(),
324	            }),
325	            multisample: wgpu::MultisampleState::default(),
326	            multiview: None,
327	            cache: None,
328	        });
329	
330	        // Depth buffer
331	        let depth_view = create_depth_texture(&device, config.width, config.height);
332	
333	        // Static geometry
334	        let track_geo = super::track::build_track_geometry();
335	        let track_surface = create_mesh_buffer(&device, &track_geo.surface.0, &track_geo.surface.1, "track_surface");
336	        let track_dividers = create_mesh_buffer(&device, &track_geo.dividers.0, &track_geo.dividers.1, "track_dividers");
337	        let track_judgment = create_mesh_buffer(&device, &track_geo.judgment.0, &track_geo.judgment.1, "track_judgment");
338	
339	        // Dynamic note buffers (pre-allocated, filled each frame)
340	        let note_taps = create_dynamic_buffer(&device, "note_taps");
341	        let note_holds = create_dynamic_buffer(&device, "note_holds");
342	        let note_arcs = create_dynamic_buffer(&device, "note_arcs");
343	        let note_arcs_hi = create_dynamic_buffer(&device, "note_arcs_hi");
344	        let note_arc_caps = create_dynamic_buffer(&device, "note_arc_caps");
345	        let note_sky = create_dynamic_buffer(&device, "note_sky");
346	        let fx_lane = create_dynamic_buffer(&device, "fx_lane");
347	        let fx_pure = create_dynamic_buffer(&device, "fx_pure");
348	        let fx_far = create_dynamic_buffer(&device, "fx_far");
349	
350	        let hud = HudRenderer::new(&device, &queue, format, assets);
351	        if hud.is_some() {
352	            log::info!("HUD renderer initialized");
353	        }
354	
355	        Self {
356	            surface,
357	            device,
358	            queue,
359	            config,
360	            pipeline,
361	            depth_view,
362	            camera,
363	            camera_buffer,
364	            camera_bind_group,
365	            tex_white,
366	            tex_track,
367	            tex_divider,
368	            tex_judgment,
369	            tex_note,
370	            tex_hold,
371	            tex_arc_body,
372	            tex_arc_body_hi,
373	            tex_arc_cap,
374	            tex_sky,
375	            tex_lane_hit,
376	            tex_hit_pure,
377	            tex_hit_far,
378	            tex_bgl,
379	            track_surface,
380	            track_dividers,
381	            track_judgment,
382	            note_taps,
383	            note_holds,
384	            note_arcs,
385	            note_arcs_hi,
386	            note_arc_caps,
387	            note_sky,
388	            fx_lane,
389	            fx_pure,
390	            fx_far,
391	            hud,
392	            show_results: false,
393	        }
394	    }
