444	    fn upload_mesh(&mut self, mesh: &(Vec<Vertex>, Vec<u32>), which: &str) {
445	        let (verts, idxs) = mesh;
446	        let buf = match which {
447	            "note_taps" => &mut self.note_taps,
448	            "note_holds" => &mut self.note_holds,
449	            "note_arcs" => &mut self.note_arcs,
450	            "note_arcs_hi" => &mut self.note_arcs_hi,
451	            "note_arc_caps" => &mut self.note_arc_caps,
452	            "note_sky" => &mut self.note_sky,
453	            "fx_lane" => &mut self.fx_lane,
454	            "fx_pure" => &mut self.fx_pure,
455	            "fx_far" => &mut self.fx_far,
456	            _ => return,
457	        };
458	        buf.index_count = idxs.len() as u32;
459	
460	        if verts.is_empty() {
461	            return;
462	        }
463	
464	        let vert_bytes = bytemuck::cast_slice(verts);
465	        let idx_bytes = bytemuck::cast_slice(idxs);
466	
467	        if vert_bytes.len() as u64 > buf.vertex.size() {
468	            buf.vertex = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
469	                label: Some(&format!("{which}_verts")),
470	                contents: vert_bytes,
471	                usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
472	            });
473	        } else {
474	            self.queue.write_buffer(&buf.vertex, 0, vert_bytes);
475	        }
476	
477	        if idx_bytes.len() as u64 > buf.index.size() {
478	            buf.index = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
479	                label: Some(&format!("{which}_idxs")),
480	                contents: idx_bytes,
481	                usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
482	            });
483	        } else {
484	            self.queue.write_buffer(&buf.index, 0, idx_bytes);
485	        }
486	    }
