500	    pub fn render(&mut self) {
501	        // Prepare HUD text before render pass
502	        let screen = [self.config.width, self.config.height];
503	        if let Some(hud) = &mut self.hud {
504	            if self.show_results {
505	                hud.prepare_results(&self.device, &self.queue, screen);
506	            } else {
507	                hud.prepare(&self.device, &self.queue, screen);
508	            }
509	        }
510	
511	        let output = match self.surface.get_current_texture() {
512	            Ok(t) => t,
513	            Err(wgpu::SurfaceError::Lost | wgpu::SurfaceError::Outdated) => {
514	                self.surface.configure(&self.device, &self.config);
515	                return;
516	            }
517	            Err(e) => {
518	                log::error!("surface error: {e:?}");
519	                return;
520	            }
521	        };
522	
523	        let view = output
524	            .texture
525	            .create_view(&wgpu::TextureViewDescriptor::default());
526	
527	        let mut encoder = self
528	            .device
529	            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
530	                label: Some("frame"),
531	            });
532	
533	        self.encode_render_pass(&mut encoder, &view, &self.depth_view);
534	
535	        self.queue.submit(std::iter::once(encoder.finish()));
536	        output.present();
537	    }
