539	    /// Encode the full render pass into the given encoder.
540	    fn encode_render_pass(
541	        &self,
542	        encoder: &mut wgpu::CommandEncoder,
543	        color_view: &wgpu::TextureView,
544	        depth_view: &wgpu::TextureView,
545	    ) {
546	        {
547	            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
548	                label: Some("main"),
549	                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
550	                    view: color_view,
551	                    resolve_target: None,
552	                    ops: wgpu::Operations {
553	                        load: wgpu::LoadOp::Clear(wgpu::Color {
554	                            r: 0.02,
555	                            g: 0.02,
556	                            b: 0.06,
557	                            a: 1.0,
558	                        }),
559	                        store: wgpu::StoreOp::Store,
560	                    },
561	                })],
562	                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
563	                    view: depth_view,
564	                    depth_ops: Some(wgpu::Operations {
565	                        load: wgpu::LoadOp::Clear(1.0),
566	                        store: wgpu::StoreOp::Store,
567	                    }),
568	                    stencil_ops: None,
569	                }),
570	                ..Default::default()
571	            });
572	
573	            pass.set_pipeline(&self.pipeline);
574	            pass.set_bind_group(0, &self.camera_bind_group, &[]);
575	
576	            // 1. Track surface (track.png)
577	            pass.set_bind_group(1, &self.tex_track, &[]);
578	            self.draw_mesh(&mut pass, &self.track_surface);
579	
580	            // 2. Lane dividers (track_lane_divider.png)
581	            pass.set_bind_group(1, &self.tex_divider, &[]);
582	            self.draw_mesh(&mut pass, &self.track_dividers);
583	
584	            // 3. Judgment line (track_critical_line.png)
585	            pass.set_bind_group(1, &self.tex_judgment, &[]);
586	            self.draw_mesh(&mut pass, &self.track_judgment);
587	
588	            // 4. Arc bodies (arc_body.png)
589	            pass.set_bind_group(1, &self.tex_arc_body, &[]);
590	            self.draw_mesh(&mut pass, &self.note_arcs);
591	
592	            // 4a. Arc bodies highlighted (arc_body_hi.png)
593	            pass.set_bind_group(1, &self.tex_arc_body_hi, &[]);
594	            self.draw_mesh(&mut pass, &self.note_arcs_hi);
595	
596	            // 4b. Arc caps (arc_cap.png)
597	            pass.set_bind_group(1, &self.tex_arc_cap, &[]);
598	            self.draw_mesh(&mut pass, &self.note_arc_caps);
599	
600	            // 5. Hold bodies (note_hold.png) — drawn before taps so heads overlay
601	            pass.set_bind_group(1, &self.tex_hold, &[]);
602	            self.draw_mesh(&mut pass, &self.note_holds);
603	
604	            // 6. Tap notes + hold heads (note.png)
605	            pass.set_bind_group(1, &self.tex_note, &[]);
606	            self.draw_mesh(&mut pass, &self.note_taps);
607	
608	            // 7. Sky notes (solid cyan — white tex × cyan vertex color)
609	            pass.set_bind_group(1, &self.tex_white, &[]);
610	            self.draw_mesh(&mut pass, &self.note_sky);
611	
612	            // 8. Lane glow (lane_hit.png)
613	            pass.set_bind_group(1, &self.tex_lane_hit, &[]);
614	            self.draw_mesh(&mut pass, &self.fx_lane);
615	
616	            // 9. Pure hit effect (hit_pure.png)
617	            pass.set_bind_group(1, &self.tex_hit_pure, &[]);
618	            self.draw_mesh(&mut pass, &self.fx_pure);
619	
620	            // 10. Far hit effect (hit_far.png)
621	            pass.set_bind_group(1, &self.tex_hit_far, &[]);
622	            self.draw_mesh(&mut pass, &self.fx_far);
623	
624	            // 11. HUD text overlay (combo + score)
625	            if let Some(hud) = &self.hud {
626	                hud.render(&mut pass);
627	            }
628	        }
629	    }
