631	    /// Capture the current frame to an RGBA image.
632	    ///
633	    /// Renders to an offscreen texture and reads back the pixels.
634	    /// Call `update_notes()` before this to set up the scene.
635	    pub fn capture_frame(&self) -> image::RgbaImage {
636	        let width = self.config.width;
637	        let height = self.config.height;
638	        let format = self.config.format;
639	
640	        // Offscreen render target
641	        let capture_tex = self.device.create_texture(&wgpu::TextureDescriptor {
642	            label: Some("capture"),
643	            size: wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
644	            mip_level_count: 1,
645	            sample_count: 1,
646	            dimension: wgpu::TextureDimension::D2,
647	            format,
648	            usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::COPY_SRC,
649	            view_formats: &[],
650	        });
651	        let capture_view = capture_tex.create_view(&wgpu::TextureViewDescriptor::default());
652	
653	        // Separate depth buffer for capture (same dimensions)
654	        let capture_depth = create_depth_texture(&self.device, width, height);
655	
656	        let mut encoder = self.device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
657	            label: Some("capture"),
658	        });
659	
660	        self.encode_render_pass(&mut encoder, &capture_view, &capture_depth);
661	
662	        // Copy texture to readback buffer
663	        let bytes_per_pixel = 4u32;
664	        let unpadded_bpr = width * bytes_per_pixel;
665	        let align = wgpu::COPY_BYTES_PER_ROW_ALIGNMENT;
666	        let padded_bpr = (unpadded_bpr + align - 1) / align * align;
667	
668	        let buffer = self.device.create_buffer(&wgpu::BufferDescriptor {
669	            label: Some("capture_readback"),
670	            size: (padded_bpr * height) as u64,
671	            usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
672	            mapped_at_creation: false,
673	        });
674	
675	        encoder.copy_texture_to_buffer(
676	            wgpu::ImageCopyTexture {
677	                texture: &capture_tex,
678	                mip_level: 0,
679	                origin: wgpu::Origin3d::ZERO,
680	                aspect: wgpu::TextureAspect::All,
681	            },
682	            wgpu::ImageCopyBuffer {
683	                buffer: &buffer,
684	                layout: wgpu::ImageDataLayout {
685	                    offset: 0,
686	                    bytes_per_row: Some(padded_bpr),
687	                    rows_per_image: Some(height),
688	                },
689	            },
690	            wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
691	        );
692	
693	        self.queue.submit(std::iter::once(encoder.finish()));
694	
695	        // Map buffer and read pixels
696	        let buffer_slice = buffer.slice(..);
697	        let (sender, receiver) = std::sync::mpsc::channel();
698	        buffer_slice.map_async(wgpu::MapMode::Read, move |result| {
699	            sender.send(result).unwrap();
700	        });
701	        self.device.poll(wgpu::Maintain::Wait);
702	        receiver.recv().unwrap().unwrap();
703	
704	        let data = buffer_slice.get_mapped_range();
705	        let mut pixels = Vec::with_capacity((width * height * 4) as usize);
706	        for chunk in data.chunks(padded_bpr as usize) {
707	            pixels.extend_from_slice(&chunk[..unpadded_bpr as usize]);
708	        }
709	        drop(data);
710	        buffer.unmap();
711	
712	        // BGRA -> RGBA conversion if needed
713	        let is_bgra = matches!(
714	            format,
715	            wgpu::TextureFormat::Bgra8Unorm | wgpu::TextureFormat::Bgra8UnormSrgb
716	        );
717	        if is_bgra {
718	            for pixel in pixels.chunks_exact_mut(4) {
719	                pixel.swap(0, 2);
720	            }
721	        }
722	
723	        image::RgbaImage::from_raw(width, height, pixels).expect("failed to create image from capture")
724	    }
725	
726	    fn draw_mesh<'a>(&'a self, pass: &mut wgpu::RenderPass<'a>, mesh: &'a MeshBuffer) {
727	        if mesh.index_count == 0 {
728	            return;
729	        }
730	        pass.set_vertex_buffer(0, mesh.vertex.slice(..));
731	        pass.set_index_buffer(mesh.index.slice(..), wgpu::IndexFormat::Uint32);
732	        pass.draw_indexed(0..mesh.index_count, 0, 0..1);
733	    }
734	}
735	
736	fn create_depth_texture(device: &wgpu::Device, width: u32, height: u32) -> wgpu::TextureView {
737	    let texture = device.create_texture(&wgpu::TextureDescriptor {
738	        label: Some("depth"),
739	        size: wgpu::Extent3d {
740	            width,
741	            height,
742	            depth_or_array_layers: 1,
743	        },
744	        mip_level_count: 1,
745	        sample_count: 1,
746	        dimension: wgpu::TextureDimension::D2,
747	        format: wgpu::TextureFormat::Depth32Float,
748	        usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
749	        view_formats: &[],
750	    });
751	    texture.create_view(&wgpu::TextureViewDescriptor::default())
752	}
