use std::sync::Arc;
use wgpu::util::DeviceExt;
use winit::window::Window;

use super::camera::{CameraService, CameraUniform};
use super::hud::HudRenderer;
use super::texture;
use super::vertex::Vertex;
use crate::chart::types::{Chart, Ms};
use crate::timing::GameClock;

const SHADER: &str = "
struct CameraUniform {
    view_proj: mat4x4<f32>,
};

@group(0) @binding(0)
var<uniform> camera: CameraUniform;

@group(1) @binding(0)
var tex: texture_2d<f32>;
@group(1) @binding(1)
var tex_sampler: sampler;

struct VsIn {
    @location(0) position: vec3<f32>,
    @location(1) color: vec4<f32>,
    @location(2) uv: vec2<f32>,
};

struct VsOut {
    @builtin(position) clip_position: vec4<f32>,
    @location(0) color: vec4<f32>,
    @location(1) uv: vec2<f32>,
};

@vertex
fn vs_main(in: VsIn) -> VsOut {
    var out: VsOut;
    out.clip_position = camera.view_proj * vec4<f32>(in.position, 1.0);
    out.color = in.color;
    out.uv = in.uv;
    return out;
}

@fragment
fn fs_main(in: VsOut) -> @location(0) vec4<f32> {
    let tex_color = textureSample(tex, tex_sampler, in.uv);
    return tex_color * in.color;
}
";

/// A GPU buffer pair for geometry.
struct MeshBuffer {
    vertex: wgpu::Buffer,
    index: wgpu::Buffer,
    index_count: u32,
}

pub struct Gpu {
    surface: wgpu::Surface<'static>,
    device: wgpu::Device,
    queue: wgpu::Queue,
    config: wgpu::SurfaceConfiguration,

    pipeline: wgpu::RenderPipeline,
    depth_view: wgpu::TextureView,

    camera: CameraService,
    camera_buffer: wgpu::Buffer,
    camera_bind_group: wgpu::BindGroup,

    // Textures (bind group per texture)
    tex_white: wgpu::BindGroup,
    tex_track: wgpu::BindGroup,
    tex_divider: wgpu::BindGroup,
    tex_judgment: wgpu::BindGroup,
    tex_note: wgpu::BindGroup,
    tex_hold: wgpu::BindGroup,
    tex_arc_body: wgpu::BindGroup,
    tex_arc_body_hi: wgpu::BindGroup,
    tex_arc_cap: wgpu::BindGroup,
    tex_sky: wgpu::BindGroup,
    tex_lane_hit: wgpu::BindGroup,
    tex_hit_pure: wgpu::BindGroup,
    tex_hit_far: wgpu::BindGroup,
    tex_bgl: wgpu::BindGroupLayout,

    // Static geometry
    track_surface: MeshBuffer,
    track_dividers: MeshBuffer,
    track_judgment: MeshBuffer,

    // Dynamic geometry (rebuilt each frame)
    note_taps: MeshBuffer,
    note_holds: MeshBuffer,
    note_arcs: MeshBuffer,
    note_arcs_hi: MeshBuffer,
    note_arc_caps: MeshBuffer,
    note_sky: MeshBuffer,
    fx_lane: MeshBuffer,
    fx_pure: MeshBuffer,
    fx_far: MeshBuffer,

    hud: Option<HudRenderer>,
    show_results: bool,
}

fn create_mesh_buffer(device: &wgpu::Device, verts: &[Vertex], idxs: &[u32], label: &str) -> MeshBuffer {
    let vertex = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some(&format!("{label}_verts")),
        contents: bytemuck::cast_slice(verts),
        usage: wgpu::BufferUsages::VERTEX,
    });
    let index = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some(&format!("{label}_idxs")),
        contents: bytemuck::cast_slice(idxs),
        usage: wgpu::BufferUsages::INDEX,
    });
    MeshBuffer {
        vertex,
        index,
        index_count: idxs.len() as u32,
    }
}

fn create_dynamic_buffer(device: &wgpu::Device, label: &str) -> MeshBuffer {
    let vertex = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some(&format!("{label}_verts")),
        size: (500 * 4 * std::mem::size_of::<Vertex>()) as u64,
        usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let index = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some(&format!("{label}_idxs")),
        size: (500 * 6 * std::mem::size_of::<u32>()) as u64,
        usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    MeshBuffer {
        vertex,
        index,
        index_count: 0,
    }
}

impl Gpu {
    pub async fn new(window: Arc<Window>, assets: &crate::assets::AssetLoader) -> Self {
        let size = window.inner_size();

        let instance = wgpu::Instance::new(wgpu::InstanceDescriptor {
            backends: wgpu::Backends::all(),
            ..Default::default()
        });

        let surface = instance
            .create_surface(window)
            .expect("failed to create surface");

        let adapter = instance
            .request_adapter(&wgpu::RequestAdapterOptions {
                power_preference: wgpu::PowerPreference::HighPerformance,
                compatible_surface: Some(&surface),
                force_fallback_adapter: false,
            })
            .await
            .expect("no suitable GPU adapter");

        log::info!("GPU: {:?}", adapter.get_info());

        let limits = if cfg!(target_os = "android") {
            wgpu::Limits::downlevel_defaults()
        } else {
            wgpu::Limits::default()
        }
        .using_resolution(adapter.limits());

        let (device, queue) = adapter
            .request_device(
                &wgpu::DeviceDescriptor {
                    label: Some("better-arc"),
                    required_features: wgpu::Features::empty(),
                    required_limits: limits,
                    ..Default::default()
                },
                None,
            )
            .await
            .expect("failed to create device");

        // Surface
        let caps = surface.get_capabilities(&adapter);
        let format = caps
            .formats
            .iter()
            .find(|f| f.is_srgb())
            .copied()
            .unwrap_or(caps.formats[0]);

        log::info!("surface present modes: {:?}", caps.present_modes);

        let present_mode = if caps.present_modes.contains(&wgpu::PresentMode::Fifo) {
            wgpu::PresentMode::Fifo
        } else {
            wgpu::PresentMode::AutoVsync
        };
        log::info!("using present mode: {:?}", present_mode);

        let config = wgpu::SurfaceConfiguration {
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
            format,
            width: size.width.max(1),
            height: size.height.max(1),
            present_mode,
            alpha_mode: caps.alpha_modes[0],
            view_formats: vec![],
            desired_maximum_frame_latency: 2,
        };
        surface.configure(&device, &config);

        // Shader
        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("shader"),
            source: wgpu::ShaderSource::Wgsl(SHADER.into()),
        });

        // Camera
        let camera = CameraService::new(config.width as f32, config.height as f32);
        let camera_uniform = CameraUniform::from_camera(&camera);

        let camera_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("camera_uniform"),
            contents: bytemuck::cast_slice(&[camera_uniform]),
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        });

        let camera_bgl = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("camera_bgl"),
            entries: &[wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::VERTEX,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            }],
        });

        let camera_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("camera_bg"),
            layout: &camera_bgl,
            entries: &[wgpu::BindGroupEntry {
                binding: 0,
                resource: camera_buffer.as_entire_binding(),
            }],
        });

        // Textures
        let tex_bgl = texture::texture_bind_group_layout(&device);
        let tex_white = texture::white_texture(&device, &queue, &tex_bgl);

        let load = |name: &str, label: &str| -> wgpu::BindGroup {
            match assets.load_bytes(&format!("extracted/{name}")) {
                Ok(bytes) => texture::load_texture_from_bytes(&device, &queue, &tex_bgl, &bytes, label),
                Err(e) => {
                    log::warn!("{name}: {e}, using white fallback");
                    texture::white_texture(&device, &queue, &tex_bgl)
                }
            }
        };

        let tex_track = load("track.png", "track");
        let tex_divider = load("track_lane_divider.png", "divider");
        let tex_judgment = load("track_critical_line.png", "judgment");
        let tex_note = load("note.png", "note");
        let tex_hold = load("note_hold.png", "note_hold");
        let tex_arc_body = load("arc_body.png", "arc_body");
        let tex_arc_body_hi = load("arc_body_hi.png", "arc_body_hi");
        let tex_arc_cap = load("arc_cap.png", "arc_cap");
        let tex_sky = load("sfx_l_note.jpg", "sky_note");
        let tex_lane_hit = load("lane_hit.png", "lane_hit");
        let tex_hit_pure = load("hit_pure.png", "hit_pure");
        let tex_hit_far = load("hit_far.png", "hit_far");

        // Pipeline (now with texture bind group)
        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("pipeline_layout"),
            bind_group_layouts: &[&camera_bgl, &tex_bgl],
            push_constant_ranges: &[],
        });

        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("main"),
            layout: Some(&pipeline_layout),
            vertex: wgpu::VertexState {
                module: &shader,
                entry_point: Some("vs_main"),
                buffers: &[Vertex::layout()],
                compilation_options: Default::default(),
            },
            fragment: Some(wgpu::FragmentState {
                module: &shader,
                entry_point: Some("fs_main"),
                targets: &[Some(wgpu::ColorTargetState {
                    format,
                    blend: Some(wgpu::BlendState::ALPHA_BLENDING),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
                compilation_options: Default::default(),
            }),
            primitive: wgpu::PrimitiveState {
                topology: wgpu::PrimitiveTopology::TriangleList,
                cull_mode: None,
                ..Default::default()
            },
            depth_stencil: Some(wgpu::DepthStencilState {
                format: wgpu::TextureFormat::Depth32Float,
                depth_write_enabled: true,
                depth_compare: wgpu::CompareFunction::Less,
                stencil: wgpu::StencilState::default(),
                bias: wgpu::DepthBiasState::default(),
            }),
            multisample: wgpu::MultisampleState::default(),
            multiview: None,
            cache: None,
        });

        // Depth buffer
        let depth_view = create_depth_texture(&device, config.width, config.height);

        // Static geometry
        let track_geo = super::track::build_track_geometry();
        let track_surface = create_mesh_buffer(&device, &track_geo.surface.0, &track_geo.surface.1, "track_surface");
        let track_dividers = create_mesh_buffer(&device, &track_geo.dividers.0, &track_geo.dividers.1, "track_dividers");
        let track_judgment = create_mesh_buffer(&device, &track_geo.judgment.0, &track_geo.judgment.1, "track_judgment");

        // Dynamic note buffers (pre-allocated, filled each frame)
        let note_taps = create_dynamic_buffer(&device, "note_taps");
        let note_holds = create_dynamic_buffer(&device, "note_holds");
        let note_arcs = create_dynamic_buffer(&device, "note_arcs");
        let note_arcs_hi = create_dynamic_buffer(&device, "note_arcs_hi");
        let note_arc_caps = create_dynamic_buffer(&device, "note_arc_caps");
        let note_sky = create_dynamic_buffer(&device, "note_sky");
        let fx_lane = create_dynamic_buffer(&device, "fx_lane");
        let fx_pure = create_dynamic_buffer(&device, "fx_pure");
        let fx_far = create_dynamic_buffer(&device, "fx_far");

        let hud = HudRenderer::new(&device, &queue, format, assets);
        if hud.is_some() {
            log::info!("HUD renderer initialized");
        }

        Self {
            surface,
            device,
            queue,
            config,
            pipeline,
            depth_view,
            camera,
            camera_buffer,
            camera_bind_group,
            tex_white,
            tex_track,
            tex_divider,
            tex_judgment,
            tex_note,
            tex_hold,
            tex_arc_body,
            tex_arc_body_hi,
            tex_arc_cap,
            tex_sky,
            tex_lane_hit,
            tex_hit_pure,
            tex_hit_far,
            tex_bgl,
            track_surface,
            track_dividers,
            track_judgment,
            note_taps,
            note_holds,
            note_arcs,
            note_arcs_hi,
            note_arc_caps,
            note_sky,
            fx_lane,
            fx_pure,
            fx_far,
            hud,
            show_results: false,
        }
    }

    /// Update note geometry for the current frame.
    pub fn update_notes(
        &mut self,
        chart: &Chart,
        clock: &GameClock,
        current_time: Ms,
        judge: &crate::judgment::GreedyJudge,
        hit_effects: &[super::track::HitEffect],
        input: &crate::input::InputManager,
    ) {
        let geo = super::track::build_note_geometry(chart, clock, current_time, judge, hit_effects, input);
        self.upload_mesh(&geo.taps, "note_taps");
        self.upload_mesh(&geo.holds, "note_holds");
        self.upload_mesh(&geo.arcs, "note_arcs");
        self.upload_mesh(&geo.arcs_hi, "note_arcs_hi");
        self.upload_mesh(&geo.arc_caps, "note_arc_caps");
        self.upload_mesh(&geo.sky, "note_sky");
        self.upload_mesh(&geo.lane_hits, "fx_lane");
        self.upload_mesh(&geo.hit_pure, "fx_pure");
        self.upload_mesh(&geo.hit_far, "fx_far");
    }

    pub fn update_hud(&mut self, combo: u32, score: u64, combo_flash: f32) {
        if let Some(hud) = &mut self.hud {
            hud.set_combo(combo, combo_flash);
            hud.set_score(score);
        }
    }

    pub fn inv_view_proj(&self) -> glam::Mat4 {
        self.camera.view_proj().inverse()
    }

    pub fn poll_wait(&self) {
        self.device.poll(wgpu::Maintain::Wait);
    }

    pub fn screen_size(&self) -> [u32; 2] {
        [self.config.width, self.config.height]
    }

    pub fn show_results(&mut self, score: &crate::judgment::ScoreState) {
        if let Some(hud) = &mut self.hud {
            hud.set_results(score);
        }
        self.show_results = true;
    }

    fn upload_mesh(&mut self, mesh: &(Vec<Vertex>, Vec<u32>), which: &str) {
        let (verts, idxs) = mesh;
        let buf = match which {
            "note_taps" => &mut self.note_taps,
            "note_holds" => &mut self.note_holds,
            "note_arcs" => &mut self.note_arcs,
            "note_arcs_hi" => &mut self.note_arcs_hi,
            "note_arc_caps" => &mut self.note_arc_caps,
            "note_sky" => &mut self.note_sky,
            "fx_lane" => &mut self.fx_lane,
            "fx_pure" => &mut self.fx_pure,
            "fx_far" => &mut self.fx_far,
            _ => return,
        };
        buf.index_count = idxs.len() as u32;

        if verts.is_empty() {
            return;
        }

        let vert_bytes = bytemuck::cast_slice(verts);
        let idx_bytes = bytemuck::cast_slice(idxs);

        if vert_bytes.len() as u64 > buf.vertex.size() {
            buf.vertex = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                label: Some(&format!("{which}_verts")),
                contents: vert_bytes,
                usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
            });
        } else {
            self.queue.write_buffer(&buf.vertex, 0, vert_bytes);
        }

        if idx_bytes.len() as u64 > buf.index.size() {
            buf.index = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                label: Some(&format!("{which}_idxs")),
                contents: idx_bytes,
                usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
            });
        } else {
            self.queue.write_buffer(&buf.index, 0, idx_bytes);
        }
    }

    pub fn resize(&mut self, width: u32, height: u32) {
        self.config.width = width;
        self.config.height = height;
        self.surface.configure(&self.device, &self.config);
        self.depth_view = create_depth_texture(&self.device, width, height);

        self.camera.recalculate_aspect(width as f32, height as f32);
        let uniform = CameraUniform::from_camera(&self.camera);
        self.queue
            .write_buffer(&self.camera_buffer, 0, bytemuck::cast_slice(&[uniform]));
    }

    pub fn render(&mut self) {
        // Prepare HUD text before render pass
        let screen = [self.config.width, self.config.height];
        if let Some(hud) = &mut self.hud {
            if self.show_results {
                hud.prepare_results(&self.device, &self.queue, screen);
            } else {
                hud.prepare(&self.device, &self.queue, screen);
            }
        }

        let output = match self.surface.get_current_texture() {
            Ok(t) => t,
            Err(wgpu::SurfaceError::Lost | wgpu::SurfaceError::Outdated) => {
                self.surface.configure(&self.device, &self.config);
                return;
            }
            Err(e) => {
                log::error!("surface error: {e:?}");
                return;
            }
        };

        let view = output
            .texture
            .create_view(&wgpu::TextureViewDescriptor::default());

        let mut encoder = self
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("frame"),
            });

        self.encode_render_pass(&mut encoder, &view, &self.depth_view);

        self.queue.submit(std::iter::once(encoder.finish()));
        output.present();
    }

    /// Encode the full render pass into the given encoder.
    fn encode_render_pass(
        &self,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &wgpu::TextureView,
        depth_view: &wgpu::TextureView,
    ) {
        {
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("main"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: color_view,
                    resolve_target: None,
                    ops: wgpu::Operations {
                        load: wgpu::LoadOp::Clear(wgpu::Color {
                            r: 0.02,
                            g: 0.02,
                            b: 0.06,
                            a: 1.0,
                        }),
                        store: wgpu::StoreOp::Store,
                    },
                })],
                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                    view: depth_view,
                    depth_ops: Some(wgpu::Operations {
                        load: wgpu::LoadOp::Clear(1.0),
                        store: wgpu::StoreOp::Store,
                    }),
                    stencil_ops: None,
                }),
                ..Default::default()
            });

            pass.set_pipeline(&self.pipeline);
            pass.set_bind_group(0, &self.camera_bind_group, &[]);

            // 1. Track surface (track.png)
            pass.set_bind_group(1, &self.tex_track, &[]);
            self.draw_mesh(&mut pass, &self.track_surface);

            // 2. Lane dividers (track_lane_divider.png)
            pass.set_bind_group(1, &self.tex_divider, &[]);
            self.draw_mesh(&mut pass, &self.track_dividers);

            // 3. Judgment line (track_critical_line.png)
            pass.set_bind_group(1, &self.tex_judgment, &[]);
            self.draw_mesh(&mut pass, &self.track_judgment);

            // 4. Arc bodies (arc_body.png)
            pass.set_bind_group(1, &self.tex_arc_body, &[]);
            self.draw_mesh(&mut pass, &self.note_arcs);

            // 4a. Arc bodies highlighted (arc_body_hi.png)
            pass.set_bind_group(1, &self.tex_arc_body_hi, &[]);
            self.draw_mesh(&mut pass, &self.note_arcs_hi);

            // 4b. Arc caps (arc_cap.png)
            pass.set_bind_group(1, &self.tex_arc_cap, &[]);
            self.draw_mesh(&mut pass, &self.note_arc_caps);

            // 5. Hold bodies (note_hold.png) — drawn before taps so heads overlay
            pass.set_bind_group(1, &self.tex_hold, &[]);
            self.draw_mesh(&mut pass, &self.note_holds);

            // 6. Tap notes + hold heads (note.png)
            pass.set_bind_group(1, &self.tex_note, &[]);
            self.draw_mesh(&mut pass, &self.note_taps);

            // 7. Sky notes (solid cyan — white tex × cyan vertex color)
            pass.set_bind_group(1, &self.tex_white, &[]);
            self.draw_mesh(&mut pass, &self.note_sky);

            // 8. Lane glow (lane_hit.png)
            pass.set_bind_group(1, &self.tex_lane_hit, &[]);
            self.draw_mesh(&mut pass, &self.fx_lane);

            // 9. Pure hit effect (hit_pure.png)
            pass.set_bind_group(1, &self.tex_hit_pure, &[]);
            self.draw_mesh(&mut pass, &self.fx_pure);

            // 10. Far hit effect (hit_far.png)
            pass.set_bind_group(1, &self.tex_hit_far, &[]);
            self.draw_mesh(&mut pass, &self.fx_far);

            // 11. HUD text overlay (combo + score)
            if let Some(hud) = &self.hud {
                hud.render(&mut pass);
            }
        }
    }

    /// Capture the current frame to an RGBA image.
    ///
    /// Renders to an offscreen texture and reads back the pixels.
    /// Call `update_notes()` before this to set up the scene.
    pub fn capture_frame(&self) -> image::RgbaImage {
        let width = self.config.width;
        let height = self.config.height;
        let format = self.config.format;

        // Offscreen render target
        let capture_tex = self.device.create_texture(&wgpu::TextureDescriptor {
            label: Some("capture"),
            size: wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format,
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::COPY_SRC,
            view_formats: &[],
        });
        let capture_view = capture_tex.create_view(&wgpu::TextureViewDescriptor::default());

        // Separate depth buffer for capture (same dimensions)
        let capture_depth = create_depth_texture(&self.device, width, height);

        let mut encoder = self.device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
            label: Some("capture"),
        });

        self.encode_render_pass(&mut encoder, &capture_view, &capture_depth);

        // Copy texture to readback buffer
        let bytes_per_pixel = 4u32;
        let unpadded_bpr = width * bytes_per_pixel;
        let align = wgpu::COPY_BYTES_PER_ROW_ALIGNMENT;
        let padded_bpr = (unpadded_bpr + align - 1) / align * align;

        let buffer = self.device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("capture_readback"),
            size: (padded_bpr * height) as u64,
            usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
            mapped_at_creation: false,
        });

        encoder.copy_texture_to_buffer(
            wgpu::ImageCopyTexture {
                texture: &capture_tex,
                mip_level: 0,
                origin: wgpu::Origin3d::ZERO,
                aspect: wgpu::TextureAspect::All,
            },
            wgpu::ImageCopyBuffer {
                buffer: &buffer,
                layout: wgpu::ImageDataLayout {
                    offset: 0,
                    bytes_per_row: Some(padded_bpr),
                    rows_per_image: Some(height),
                },
            },
            wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
        );

        self.queue.submit(std::iter::once(encoder.finish()));

        // Map buffer and read pixels
        let buffer_slice = buffer.slice(..);
        let (sender, receiver) = std::sync::mpsc::channel();
        buffer_slice.map_async(wgpu::MapMode::Read, move |result| {
            sender.send(result).unwrap();
        });
        self.device.poll(wgpu::Maintain::Wait);
        receiver.recv().unwrap().unwrap();

        let data = buffer_slice.get_mapped_range();
        let mut pixels = Vec::with_capacity((width * height * 4) as usize);
        for chunk in data.chunks(padded_bpr as usize) {
            pixels.extend_from_slice(&chunk[..unpadded_bpr as usize]);
        }
        drop(data);
        buffer.unmap();

        // BGRA -> RGBA conversion if needed
        let is_bgra = matches!(
            format,
            wgpu::TextureFormat::Bgra8Unorm | wgpu::TextureFormat::Bgra8UnormSrgb
        );
        if is_bgra {
            for pixel in pixels.chunks_exact_mut(4) {
                pixel.swap(0, 2);
            }
        }

        image::RgbaImage::from_raw(width, height, pixels).expect("failed to create image from capture")
    }

    fn draw_mesh<'a>(&'a self, pass: &mut wgpu::RenderPass<'a>, mesh: &'a MeshBuffer) {
        if mesh.index_count == 0 {
            return;
        }
        pass.set_vertex_buffer(0, mesh.vertex.slice(..));
        pass.set_index_buffer(mesh.index.slice(..), wgpu::IndexFormat::Uint32);
        pass.draw_indexed(0..mesh.index_count, 0, 0..1);
    }
}

fn create_depth_texture(device: &wgpu::Device, width: u32, height: u32) -> wgpu::TextureView {
    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("depth"),
        size: wgpu::Extent3d {
            width,
            height,
            depth_or_array_layers: 1,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: wgpu::TextureFormat::Depth32Float,
        usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
        view_formats: &[],
    });
    texture.create_view(&wgpu::TextureViewDescriptor::default())
}

