// Utility functions for creating wgpu render pipelines for instanced rendering.
// Uses MeshVertex + InstanceData vertex layout.

use wgpu::util::DeviceExt;

use super::vertex::{InstanceData, MeshVertex};

// === Common blend states ===

/// Standard alpha blending (SrcAlpha, OneMinusSrcAlpha).
pub const BLEND_ALPHA: wgpu::BlendState = wgpu::BlendState {
    color: wgpu::BlendComponent {
        src_factor: wgpu::BlendFactor::SrcAlpha,
        dst_factor: wgpu::BlendFactor::OneMinusSrcAlpha,
        operation: wgpu::BlendOperation::Add,
    },
    alpha: wgpu::BlendComponent {
        src_factor: wgpu::BlendFactor::One,
        dst_factor: wgpu::BlendFactor::OneMinusSrcAlpha,
        operation: wgpu::BlendOperation::Add,
    },
};

/// Additive blending (SrcAlpha, One) — for single_line/beatline.
pub const BLEND_ADDITIVE: wgpu::BlendState = wgpu::BlendState {
    color: wgpu::BlendComponent {
        src_factor: wgpu::BlendFactor::SrcAlpha,
        dst_factor: wgpu::BlendFactor::One,
        operation: wgpu::BlendOperation::Add,
    },

        multisample: wgpu::MultisampleState::default(),
        multiview: None,
        cache: None,
    })
}

// === Mesh creation ===

/// Create a unit quad mesh (-0.5 to 0.5 on X, 0 to 1 on Z, Y=0).
///
/// Returns (vertex_buffer, index_buffer, index_count).
/// UV mapping: (0,0) at (-0.5, 0, 0) to (1,1) at (0.5, 0, 1).
pub fn create_quad_mesh(device: &wgpu::Device) -> (wgpu::Buffer, wgpu::Buffer, u32) {
    let vertices: [MeshVertex; 4] = [
        MeshVertex { position: [-0.5, 0.0, 0.0], uv: [0.0, 0.0] }, // bottom-left
        MeshVertex { position: [ 0.5, 0.0, 0.0], uv: [1.0, 0.0] }, // bottom-right
        MeshVertex { position: [ 0.5, 0.0, 1.0], uv: [1.0, 1.0] }, // top-right
        MeshVertex { position: [-0.5, 0.0, 1.0], uv: [0.0, 1.0] }, // top-left
    ];

    let indices: [u32; 6] = [
        0, 1, 2,
        0, 2, 3,
    ];

    let vertex_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("quad_vertices"),
        contents: bytemuck::cast_slice(&vertices),
        usage: wgpu::BufferUsages::VERTEX,
    });

    let index_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("quad_indices"),
        contents: bytemuck::cast_slice(&indices),
        usage: wgpu::BufferUsages::INDEX,
    });

    (vertex_buffer, index_buffer, indices.len() as u32)
}

/// Convert a MeshData (Vec3 positions, no UVs) into GPU buffers of MeshVertex.
///
/// UVs are set to (0, 0) as placeholder since arc body meshes don't use texture UVs.
/// Returns (vertex_buffer, index_buffer, index_count).
pub fn create_mesh_from_data(
    device: &wgpu::Device,
    mesh: &crate::gameplay::arc_mesh::MeshData,
) -> (wgpu::Buffer, wgpu::Buffer, u32) {
    let vertices: Vec<MeshVertex> = mesh
        .vertices
        .iter()
        .map(|v| MeshVertex {
            position: [v.x, v.y, v.z],
            uv: [0.0, 0.0],
        })
        .collect();

    let vertex_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("mesh_vertices"),
        contents: bytemuck::cast_slice(&vertices),
        usage: wgpu::BufferUsages::VERTEX,
    });

    let index_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("mesh_indices"),
        contents: bytemuck::cast_slice(&mesh.triangles),
        usage: wgpu::BufferUsages::INDEX,
    });

    (vertex_buffer, index_buffer, mesh.triangles.len() as u32)
}

