#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Easing {
    S,
    B,
    Si,
    So,
    SiSi,
    SiSo,
    SoSi,
    SoSo,
    SiB,
    SoB,
    BiS,
    BSi,
    BSo,
    BB,
}

impl Easing {
    /// Apply this easing to interpolate arc (x, y) at parameter t in [0, 1].
    ///
    /// Each easing type specifies independent functions for X and Y axes.
    /// Source: Ghidra -- ArcEasing (Arcaea 6.13.10c)
    pub fn apply(&self, x1: f32, x2: f32, y1: f32, y2: f32, t: f32) -> (f32, f32) {
        use std::f32::consts::FRAC_PI_2;

        let lin = |a: f32, b: f32, t: f32| (1.0 - t) * a + t * b;
        let sin_in = |a: f32, b: f32, t: f32| a + (b - a) * (FRAC_PI_2 * t).sin();
        let sin_out = |a: f32, b: f32, t: f32| a + (b - a) * (1.0 - (FRAC_PI_2 * t).cos());
        let bez = |a: f32, b: f32, t: f32| {
            let mt = 1.0 - t;
            mt * mt * mt * a + 3.0 * mt * mt * t * a + 3.0 * mt * t * t * b + t * t * t * b
        };

        match self {
            Easing::S    => (lin(x1, x2, t),     lin(y1, y2, t)),
            Easing::B    => (bez(x1, x2, t),     bez(y1, y2, t)),
            Easing::Si   => (sin_in(x1, x2, t),  lin(y1, y2, t)),
            Easing::So   => (sin_out(x1, x2, t), lin(y1, y2, t)),
            Easing::SiSi => (sin_in(x1, x2, t),  sin_in(y1, y2, t)),
            Easing::SiSo => (sin_in(x1, x2, t),  sin_out(y1, y2, t)),
            Easing::SoSi => (sin_out(x1, x2, t), sin_in(y1, y2, t)),
            Easing::SoSo => (sin_out(x1, x2, t), sin_out(y1, y2, t)),
            Easing::SiB  => (sin_in(x1, x2, t),  bez(y1, y2, t)),
            Easing::SoB  => (sin_out(x1, x2, t), bez(y1, y2, t)),
            Easing::BiS  => (bez(x1, x2, t),     lin(y1, y2, t)),
            Easing::BSi  => (bez(x1, x2, t),     sin_in(y1, y2, t)),
            Easing::BSo  => (bez(x1, x2, t),     sin_out(y1, y2, t)),
            Easing::BB   => (bez(x1, x2, t),     bez(y1, y2, t)),
        }
    }
}

