// ArcCreate CameraService 1:1 port
// Reference: re/ArcCreate/Assets/Scripts/Gameplay/Camera/CameraService.cs

use glam::{Mat4, Vec3};
use crate::values::*;

/// ArcCreate-aligned look-at target point.
/// From CameraService.UpdateCamera: LookRotation((0,-5.5,-20) - ResetPosition, up)
const LOOK_AT_TARGET: Vec3 = Vec3::new(0.0, -5.5, -20.0);

pub struct CameraService {
    // Current state
    pub position: Vec3,
    pub fov: f32,

    // Tilt
    current_tilt: f32,
    current_arc_pos: f32,
    is_reset: bool,
    tilt_factor_external: f32,

    // External modifiers (for scenecontrol)
    fov_external: f32,
    translation_external: Vec3,

    // Aspect
    aspect: f32,
    aspect_adjustment: f32,

    // Screen
    screen_width: f32,
    screen_height: f32,
}

impl CameraService {
    pub fn new(width: f32, height: f32) -> Self {
        let mut cam = Self {
            position: Vec3::ZERO,
            fov: 50.0,
            current_tilt: 0.0,
            current_arc_pos: 0.0,
            is_reset: true,
            tilt_factor_external: 1.0,
            fov_external: 0.0,
            translation_external: Vec3::ZERO,
            aspect: width / height,
            aspect_adjustment: 0.0,
            screen_width: width,
            screen_height: height,
        };
        cam.recalculate_aspect(width, height);
        cam.reset_position();
        cam
    }

    pub fn recalculate_aspect(&mut self, width: f32, height: f32) {
        self.screen_width = width;
        self.screen_height = height;
        self.aspect = width / height;
        let equivalent_height = height / (width / 16.0);
        self.aspect_adjustment = ((equivalent_height - 9.0) / 3.0).clamp(0.0, 1.0);
        self.reset_position();
    }

    fn reset_position(&mut self) {
        let a = self.aspect_adjustment;
        self.position = Vec3::new(
            0.0,
            CAMERA_Y,
            lerp(CAMERA_Z, CAMERA_Z_TABLET, a),
        );
        self.fov = lerp(50.0, 65.0, a) + self.fov_external;
    }

    fn reset_rotation_x(&self) -> f32 {
        lerp(CAMERA_ROT_X, CAMERA_ROT_X_TABLET, self.aspect_adjustment)
    }

    /// Call each frame with accumulated arc X world positions.
    pub fn add_tilt(&mut self, arc_world_x: f32) {
        self.current_arc_pos += arc_world_x;
    }

    /// Update camera tilt. Called at end of frame.
    pub fn update(&mut self, delta_time: f32) {
        self.update_tilt(delta_time);
    }

    fn update_tilt(&mut self, delta_time: f32) {
        if !self.is_reset {
            self.current_tilt = 0.0;
            return;
        }

        let target = -(self.current_arc_pos / LANE_WIDTH).clamp(-1.0, 1.0) * CAMERA_ARC_POS_SCALAR;
        let delta = target - self.current_tilt;
        if delta.abs() >= 0.001 {
            let dt = delta_time.min(0.1);
            self.current_tilt += CAMERA_TILT_SPEED * delta * dt;
        } else {
            self.current_tilt = target;
        }

        self.current_tilt *= self.tilt_factor_external;
        self.current_arc_pos = 0.0;
    }

    /// Camera events will modify position/rotation in Phase 10.
    /// For now, returns the base position (possibly modified by events later).
    pub fn effective_position(&self) -> Vec3 {
        self.position + self.translation_external
    }

    fn up_vector(&self) -> Vec3 {
        Vec3::new(
            self.current_tilt,
            1.0 - self.current_tilt.abs(),
            0.0,
        ).normalize()
    }

    pub fn view_matrix(&self) -> Mat4 {
        let eye = self.effective_position();
        let up = self.up_vector();
        Mat4::look_at_rh(eye, LOOK_AT_TARGET, up)
    }

    pub fn projection_matrix(&self) -> Mat4 {
        Mat4::perspective_rh(
            self.fov.to_radians(),
            self.aspect,
            0.01,
            1000.0,
        )
    }

    pub fn view_proj(&self) -> Mat4 {
        self.projection_matrix() * self.view_matrix()
    }

    pub fn calculate_depth_squared(&self, world_pos: Vec3) -> f32 {
        (self.effective_position() - world_pos).length_squared()
    }

    // === External setters (for scenecontrol, Phase 10) ===

    pub fn set_properties_external(&mut self, fov: f32, tilt_factor: f32) {
        self.fov_external = fov;
        self.tilt_factor_external = tilt_factor;
    }

    pub fn set_translation_external(&mut self, translation: Vec3) {
        self.translation_external = translation;
    }

    pub fn set_is_reset(&mut self, is_reset: bool) {
        self.is_reset = is_reset;
    }
}

#[repr(C)]
#[derive(Copy, Clone, bytemuck::Pod, bytemuck::Zeroable)]
pub struct CameraUniform {
    pub view_proj: [[f32; 4]; 4],
}

impl CameraUniform {
    pub fn from_camera(camera: &CameraService) -> Self {
        Self {
            view_proj: camera.view_proj().to_cols_array_2d(),
        }
    }
}

fn lerp(a: f32, b: f32, t: f32) -> f32 {
    a + (b - a) * t
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_16_9_defaults() {
        let cam = CameraService::new(1920.0, 1080.0);
        assert!((cam.position.y - 9.0).abs() < 0.01);
        assert!((cam.position.z - 9.0).abs() < 0.1);
        assert!((cam.fov - 50.0).abs() < 1.0);
        assert!(cam.aspect_adjustment < 0.1);
    }

    #[test]
    fn test_4_3_tablet() {
        let cam = CameraService::new(2048.0, 1536.0);
        assert!(cam.aspect_adjustment > 0.9, "aspect_adjustment={}", cam.aspect_adjustment);
        assert!((cam.fov - 65.0).abs() < 2.0, "fov={}", cam.fov);
        assert!((cam.position.z - 8.0).abs() < 0.2, "z={}", cam.position.z);
    }

    #[test]
    fn test_tilt_zero_at_start() {
        let cam = CameraService::new(1920.0, 1080.0);
        assert_eq!(cam.current_tilt, 0.0);
        let up = cam.up_vector();
        assert!((up.x).abs() < 1e-5);
        assert!((up.y - 1.0).abs() < 1e-5);
    }

    #[test]
    fn test_view_proj_not_zero() {
        let cam = CameraService::new(1920.0, 1080.0);
        let vp = cam.view_proj();
        let det = vp.determinant();
        assert!(det.abs() > 1e-10, "view_proj should be non-singular");
    }

    #[test]
    fn test_depth_squared() {
        let cam = CameraService::new(1920.0, 1080.0);
        let d = cam.calculate_depth_squared(Vec3::ZERO);
        // eye at (0,9,9), origin at (0,0,0) → distance² = 81+81 = 162
        assert!((d - 162.0).abs() < 1.0);
    }
}
